package com.spoopdps;

import java.awt.Color;
import lombok.Value;

@Value
class AttackMarker
{
	private static final Color BOOM_COLOR = new Color(255, 180, 60);
	private static final Color WHIFF_COLOR = new Color(150, 150, 150);

	long elapsedMs;
	boolean boom;

	String getSymbol()
	{
		return boom ? "\uD83D\uDCA5" : "\uD83D\uDCA8";
	}

	Color getLineColor()
	{
		return boom ? BOOM_COLOR : WHIFF_COLOR;
	}
}

package com.spoopdps;

import java.text.DecimalFormat;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import lombok.Getter;
import net.runelite.client.util.QuantityFormatter;

@Getter
class BossRecap
{
	private final String bossName;
	private final int bossLevel;
	private final String duration;
	private final double yourDps;
	private final double personalBest;
	private final boolean newPersonalBest;
	private final int yourDamage;
	private final double yourDamagePercent;
	private final double boomPercent;
	private final double whiffPercent;
	private final int boomCount;
	private final int whiffCount;
	private final List<BossRecapMember> members;

	BossRecap(String bossName, int bossLevel, String duration, double yourDps, double personalBest,
		boolean newPersonalBest, int yourDamage, double yourDamagePercent, double boomPercent, double whiffPercent,
		int boomCount, int whiffCount, List<BossRecapMember> members)
	{
		this.bossName = bossName;
		this.bossLevel = bossLevel;
		this.duration = duration;
		this.yourDps = yourDps;
		this.personalBest = personalBest;
		this.newPersonalBest = newPersonalBest;
		this.yourDamage = yourDamage;
		this.yourDamagePercent = yourDamagePercent;
		this.boomPercent = boomPercent;
		this.whiffPercent = whiffPercent;
		this.boomCount = boomCount;
		this.whiffCount = whiffCount;
		this.members = members;
	}

	String toClipboardText()
	{
		DecimalFormat percentFormat = new DecimalFormat("#0");
		List<BossRecapMember> sorted = new ArrayList<>(members);
		sorted.sort(Comparator.comparingInt(BossRecapMember::getDamage).reversed());

		StringBuilder sb = new StringBuilder();
		if (bossName != null && !bossName.isEmpty())
		{
			sb.append(bossName);
		}

		for (BossRecapMember member : sorted)
		{
			if (member.getDamage() <= 0)
			{
				continue;
			}

			if (sb.length() > 0)
			{
				sb.append('\n');
			}

			sb.append(member.getName())
				.append("  ")
				.append(percentFormat.format(member.getDamagePercent()))
				.append("%  ")
				.append(QuantityFormatter.formatNumber(member.getDamage()));
		}

		return sb.toString();
	}

	@Getter
	static class BossRecapMember
	{
		private final String name;
		private final double dps;
		private final int damage;
		private final double damagePercent;
		private final boolean localPlayer;

		BossRecapMember(String name, double dps, int damage, double damagePercent, boolean localPlayer)
		{
			this.name = name;
			this.dps = dps;
			this.damage = damage;
			this.damagePercent = damagePercent;
			this.localPlayer = localPlayer;
		}
	}
}

package com.spoopdps;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.Prayer;

@Getter
class CombatSession
{
	private final Instant startTime;
	private Instant endTime;
	private final PlayerSnapshot playerSnapshot;
	private final Map<Integer, TargetStats> targets = new LinkedHashMap<>();
	private final List<HitRecord> hits = new ArrayList<>();
	private final List<DpsSample> samples = new ArrayList<>();
	private final List<PrayerMarker> prayerMarkers = new ArrayList<>();
	private final List<AttackMarker> attackMarkers = new ArrayList<>();

	private int focusTargetIndex = -1;
	private int totalDamage;
	private int hitCount;
	private int attackCount;
	private int boomCount;
	private int whiffCount;
	private int maxHit;
	private int rollingWindowMs = 3000;
	private int chartWarmupMs = 3000;

	@Setter
	private boolean targetKilled;

	@Setter
	private ExpectedDpsEstimate expectedDps;

	@Setter
	private BossRecap bossRecap;

	CombatSession(PlayerSnapshot playerSnapshot)
	{
		this.startTime = Instant.now();
		this.playerSnapshot = playerSnapshot;
	}

	void setRollingWindowMs(int rollingWindowMs)
	{
		this.rollingWindowMs = Math.max(1000, rollingWindowMs);
	}

	void setChartWarmupMs(int chartWarmupMs)
	{
		this.chartWarmupMs = Math.max(0, chartWarmupMs);
	}

	TargetStats getOrCreateTarget(int index, int npcId, String name, int combatLevel, int hpPercent)
	{
		return targets.computeIfAbsent(index, i -> new TargetStats(i, npcId, name, combatLevel, hpPercent));
	}

	boolean isBossFight()
	{
		TargetStats primary = getPrimaryTarget();
		return primary != null && BossNpcIds.isBoss(primary.getNpcId());
	}

	boolean isTracking(int npcIndex)
	{
		return targets.containsKey(npcIndex);
	}

	void recordAttack(TargetStats target, int amount, boolean maxHitSplat)
	{
		attackCount++;
		focusTargetIndex = target.getNpcIndex();
		long elapsed = getElapsedMs();

		if (amount <= 0)
		{
			whiffCount++;
			attackMarkers.add(new AttackMarker(elapsed, false));
			return;
		}

		if (maxHitSplat || isBoomHit(amount))
		{
			boomCount++;
			attackMarkers.add(new AttackMarker(elapsed, true));
		}

		totalDamage += amount;
		hitCount++;
		maxHit = Math.max(maxHit, amount);
		target.addHit(amount);
		hits.add(new HitRecord(elapsed, amount));
		recordSample(elapsed);
	}

	private boolean isBoomHit(int amount)
	{
		return expectedDps != null && amount >= expectedDps.getMaxHit();
	}

	double getBoomPercent()
	{
		if (attackCount <= 0)
		{
			return 0;
		}
		return 100.0 * boomCount / attackCount;
	}

	double getWhiffPercent()
	{
		if (attackCount <= 0)
		{
			return 0;
		}
		return 100.0 * whiffCount / attackCount;
	}

	String getLuckSummary()
	{
		if (attackCount <= 0)
		{
			return "";
		}
		return String.format("Boom %d  ·  Miss %d", boomCount, whiffCount);
	}

	void recordTickSample()
	{
		if (!isActive() || hits.isEmpty())
		{
			return;
		}

		long elapsed = getElapsedMs();
		if (!samples.isEmpty() && elapsed - samples.get(samples.size() - 1).getElapsedMs() < 600)
		{
			return;
		}

		recordSample(elapsed);
	}

	private void recordSample(long elapsedMs)
	{
		if (elapsedMs < chartWarmupMs)
		{
			return;
		}

		double rollingDps = calculateRollingDps(elapsedMs);
		samples.add(new DpsSample(elapsedMs, rollingDps, totalDamage));
	}

	double calculateRollingDps(long atElapsedMs)
	{
		if (atElapsedMs < chartWarmupMs)
		{
			return 0;
		}

		long windowStart = Math.max(0, atElapsedMs - rollingWindowMs);
		int damageInWindow = 0;
		for (HitRecord hit : hits)
		{
			if (hit.getElapsedMs() > windowStart && hit.getElapsedMs() <= atElapsedMs)
			{
				damageInWindow += hit.getDamage();
			}
		}

		return damageInWindow / (rollingWindowMs / 1000.0);
	}

	void end()
	{
		endTime = Instant.now();
		if (!hits.isEmpty())
		{
			recordSample(getElapsedMs());
		}
	}

	boolean isActive()
	{
		return endTime == null;
	}

	TargetStats getPrimaryTarget()
	{
		if (focusTargetIndex >= 0 && targets.containsKey(focusTargetIndex))
		{
			return targets.get(focusTargetIndex);
		}

		return targets.values().stream()
			.max(Comparator.comparingInt(TargetStats::getDamage))
			.orElse(null);
	}

	List<TargetStats> getTargetsByDamage()
	{
		List<TargetStats> sorted = new ArrayList<>(targets.values());
		sorted.sort(Comparator.comparingInt(TargetStats::getDamage).reversed());
		return sorted;
	}

	List<DpsSample> getSamples()
	{
		return Collections.unmodifiableList(samples);
	}

	List<PrayerMarker> getPrayerMarkers()
	{
		return Collections.unmodifiableList(prayerMarkers);
	}

	List<AttackMarker> getAttackMarkers()
	{
		return Collections.unmodifiableList(attackMarkers);
	}

	void recordPrayerOn(Prayer prayer, long elapsedMs)
	{
		for (int i = prayerMarkers.size() - 1; i >= 0; i--)
		{
			PrayerMarker marker = prayerMarkers.get(i);
			if (marker.getPrayer() == prayer && elapsedMs - marker.getElapsedMs() < 600)
			{
				return;
			}
		}

		prayerMarkers.add(new PrayerMarker(
			elapsedMs,
			prayer,
			PrayerStyles.label(prayer),
			PrayerStyles.color(prayer)
		));
	}

	long getChartWarmupMs()
	{
		return chartWarmupMs;
	}

	long getChartDurationMs()
	{
		long elapsed = getElapsedMs();
		return Math.max(0, elapsed - chartWarmupMs);
	}

	double getPeakRollingDps()
	{
		return samples.stream().mapToDouble(DpsSample::getRollingDps).max().orElse(0);
	}

	double getLowRollingDps()
	{
		return samples.stream()
			.filter(s -> s.getRollingDps() > 0)
			.mapToDouble(DpsSample::getRollingDps)
			.min()
			.orElse(0);
	}

	double getAverageRollingDps()
	{
		return samples.stream().mapToDouble(DpsSample::getRollingDps).average().orElse(0);
	}

	double getDps()
	{
		long elapsedMs = getElapsedMs();
		if (elapsedMs <= 0 || totalDamage == 0)
		{
			return 0;
		}
		return totalDamage / (elapsedMs / 1000.0);
	}

	long getElapsedMs()
	{
		Instant end = endTime != null ? endTime : Instant.now();
		return Duration.between(startTime, end).toMillis();
	}

	String getFormattedDuration()
	{
		long seconds = getElapsedMs() / 1000;
		long minutes = seconds / 60;
		seconds = seconds % 60;
		if (minutes > 0)
		{
			return String.format("%d:%02d", minutes, seconds);
		}
		return seconds + "s";
	}

	String getHistoryLabel()
	{
		TargetStats primary = getPrimaryTarget();
		return primary != null ? primary.getName() : "Unknown";
	}

	String getEfficiencySummary()
	{
		if (samples.size() < 2)
		{
			return "";
		}
		return String.format("Peak %s  ·  Low %s  ·  Avg %s",
			formatDps(getPeakRollingDps()),
			formatDps(getLowRollingDps()),
			formatDps(getAverageRollingDps()));
	}

	private static String formatDps(double dps)
	{
		return String.format("%.1f", dps);
	}
}

package com.spoopdps;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Deque;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.HitsplatID;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;

@Singleton
class CombatTracker
{
	@Inject
	private Client client;

	@Inject
	private SpoopDpsConfig config;

	@Inject
	private ExpectedDpsCalculator expectedDpsCalculator;

	@Inject
	private PersonalBestStore personalBestStore;

	@Inject
	private PartyDamageTracker partyDamageTracker;

	@Getter
	private CombatSession activeSession;

	private final Deque<CombatSession> history = new ArrayDeque<>();
	private int historyGeneration;

	private Instant lastActivity = Instant.EPOCH;

	private final boolean[] prayerActive = new boolean[Prayer.values().length];
	private boolean prayersInitialized;

	void recordPlayerAttack(NPC target, Hitsplat hitsplat)
	{
		lastActivity = Instant.now();
		int index = target.getIndex();
		int amount = hitsplat.getAmount();

		if (activeSession != null && config.splitOnNewTarget() && activeSession.isTracking(index) == false)
		{
			endCombat();
		}

		if (activeSession == null)
		{
			CombatSession session = new CombatSession(capturePlayerSnapshot());
			session.setRollingWindowMs(config.rollingWindowSeconds() * 1000);
			session.setChartWarmupMs(config.chartWarmupSeconds() * 1000);
			activeSession = session;
			initializePrayers();
		}

		String name = target.getName() != null ? target.getName() : "Unknown";
		TargetStats targetStats = activeSession.getOrCreateTarget(
			index, target.getId(), name, target.getCombatLevel(), getHpPercent(target));
		targetStats.setHpPercent(getHpPercent(target));
		updateExpectedDps(target);
		activeSession.recordAttack(targetStats, amount, isMaxHitSplat(hitsplat));
	}

	private void updateExpectedDps(NPC target)
	{
		if (!config.showExpectedDps())
		{
			return;
		}

		ExpectedDpsEstimate estimate = expectedDpsCalculator.calculate(target);
		activeSession.setExpectedDps(estimate);
	}

	void recordCombatActivity()
	{
		lastActivity = Instant.now();
	}

	void onTargetDeath(NPC npc)
	{
		if (!config.endOnKill() || activeSession == null || !activeSession.isActive())
		{
			return;
		}

		if (activeSession.isTracking(npc.getIndex()))
		{
			activeSession.setTargetKilled(true);
			endCombat();
		}
	}

	void tick(int timeoutSeconds)
	{
		if (activeSession == null || !activeSession.isActive())
		{
			return;
		}

		if (isStillEngagedInFight() || isPlayerConsuming())
		{
			lastActivity = Instant.now();
		}

		if (Duration.between(lastActivity, Instant.now()).getSeconds() >= timeoutSeconds)
		{
			endCombat();
			return;
		}

		activeSession.recordTickSample();
		updateInteractingTargetHp();
		checkPrayers();
	}

	void endCombat()
	{
		if (activeSession == null || !activeSession.isActive())
		{
			return;
		}

		CombatSession session = activeSession;
		session.end();

		boolean newPersonalBest = false;
		TargetStats primary = session.getPrimaryTarget();
		if (primary != null)
		{
			newPersonalBest = personalBestStore.checkAndUpdate(
				primary.getName(),
				primary.getCombatLevel(),
				session.getDps(),
				session.getTotalDamage(),
				session.getElapsedMs());
		}

		session.setBossRecap(partyDamageTracker.onCombatEnd(session, newPersonalBest));
		addToHistory(session);
		activeSession = null;
		resetPrayerState();
	}

	void reset()
	{
		if (activeSession != null && activeSession.isActive())
		{
			activeSession.end();
			addToHistory(activeSession);
		}
		activeSession = null;
		history.clear();
		historyGeneration++;
		lastActivity = Instant.EPOCH;
		resetPrayerState();
		partyDamageTracker.clearRecap();
	}

	private static boolean isMaxHitSplat(Hitsplat hitsplat)
	{
		switch (hitsplat.getHitsplatType())
		{
			case HitsplatID.DAMAGE_MAX_ME:
			case HitsplatID.DAMAGE_MAX_ME_CYAN:
			case HitsplatID.DAMAGE_MAX_ME_ORANGE:
			case HitsplatID.DAMAGE_MAX_ME_YELLOW:
			case HitsplatID.DAMAGE_MAX_ME_WHITE:
			case HitsplatID.DAMAGE_MAX_ME_POISE:
				return true;
			default:
				return false;
		}
	}

	private void initializePrayers()
	{
		prayersInitialized = true;
		long elapsed = activeSession.getElapsedMs();

		for (Prayer prayer : Prayer.values())
		{
			if (!PrayerStyles.isChartPrayer(prayer))
			{
				continue;
			}

			boolean active = client.isPrayerActive(prayer);
			prayerActive[prayer.ordinal()] = active;
			if (active)
			{
				activeSession.recordPrayerOn(prayer, elapsed);
			}
		}
	}

	private void checkPrayers()
	{
		if (!config.showPrayerMarkers() || !prayersInitialized)
		{
			return;
		}

		long elapsed = activeSession.getElapsedMs();

		for (Prayer prayer : Prayer.values())
		{
			if (!PrayerStyles.isChartPrayer(prayer))
			{
				continue;
			}

			boolean active = client.isPrayerActive(prayer);
			if (active && !prayerActive[prayer.ordinal()])
			{
				activeSession.recordPrayerOn(prayer, elapsed);
			}
			prayerActive[prayer.ordinal()] = active;
		}
	}

	private void resetPrayerState()
	{
		prayersInitialized = false;
		Arrays.fill(prayerActive, false);
	}

	CombatSession getOverlaySession()
	{
		if (activeSession != null)
		{
			return activeSession;
		}
		return history.peekFirst();
	}

	boolean isInCombat()
	{
		return activeSession != null;
	}

	int getHistoryGeneration()
	{
		return historyGeneration;
	}

	List<CombatSession> getHistory()
	{
		return new ArrayList<>(history);
	}

	List<EnemyHistorySummary> getHistorySummaries()
	{
		Map<String, EnemyHistorySummary> summaries = new LinkedHashMap<>();
		for (CombatSession session : history)
		{
			String name = session.getHistoryLabel();
			summaries.computeIfAbsent(name, EnemyHistorySummary::new).addSession(session);
		}
		return new ArrayList<>(summaries.values());
	}

	private void addToHistory(CombatSession session)
	{
		if (session.getTotalDamage() <= 0)
		{
			return;
		}

		history.addFirst(session);
		historyGeneration++;
		while (history.size() > config.historySize())
		{
			history.removeLast();
		}
	}

	private PlayerSnapshot capturePlayerSnapshot()
	{
		return new PlayerSnapshot(
			client.getLocalPlayer().getCombatLevel(),
			client.getBoostedSkillLevel(Skill.ATTACK),
			client.getBoostedSkillLevel(Skill.STRENGTH),
			client.getBoostedSkillLevel(Skill.DEFENCE),
			client.getBoostedSkillLevel(Skill.RANGED),
			client.getBoostedSkillLevel(Skill.MAGIC),
			client.getBoostedSkillLevel(Skill.HITPOINTS)
		);
	}

	private boolean isStillEngagedInFight()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return false;
		}

		if (!(player.getInteracting() instanceof NPC))
		{
			return false;
		}

		NPC npc = (NPC) player.getInteracting();
		return !npc.isDead() && activeSession.isTracking(npc.getIndex());
	}

	private boolean isPlayerConsuming()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return false;
		}

		return isConsumingAnimation(player.getAnimation());
	}

	private static boolean isConsumingAnimation(int animation)
	{
		switch (animation)
		{
			case 829: // Eat
			case 1159: // Eat
			case 1244: // Eat
			case 2779: // Karambwan
			case 719: // Drink
			case 881: // Drink
			case 893: // Drink
			case 1060: // Drink
			case 1061: // Drink
			case 1062: // Drink
				return true;
			default:
				return false;
		}
	}

	private void updateInteractingTargetHp()
	{
		Player player = client.getLocalPlayer();
		if (player == null || !(player.getInteracting() instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) player.getInteracting();
		if (!activeSession.isTracking(npc.getIndex()))
		{
			return;
		}

		TargetStats stats = activeSession.getOrCreateTarget(
			npc.getIndex(),
			npc.getId(),
			npc.getName() != null ? npc.getName() : "Unknown",
			npc.getCombatLevel(),
			getHpPercent(npc)
		);
		stats.setHpPercent(getHpPercent(npc));
	}

	private static int getHpPercent(NPC npc)
	{
		int scale = npc.getHealthScale();
		if (scale <= 0)
		{
			return 100;
		}
		return (npc.getHealthRatio() * 100) / scale;
	}
}

package com.spoopdps;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.text.DecimalFormat;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

class DpsChartPanel extends JPanel
{
	private static final DecimalFormat DPS_FORMAT = new DecimalFormat("#0");
	private static final Color LINE_COLOR = new Color(198, 40, 40);
	private static final Color EXPECTED_LINE_COLOR = new Color(100, 180, 255);
	private static final Color GRID_COLOR = new Color(60, 60, 60);
	private static final Color LABEL_COLOR = new Color(150, 150, 150);

	private static final int PAD_LEFT = 28;
	private static final int PAD_RIGHT = 6;
	private static final int PAD_TOP = 6;
	private static final int PAD_BOTTOM = 42;
	private static final int MARKER_SIZE = 10;
	private static final int EMOJI_MARKER_HEIGHT = 14;
	private static final BasicStroke MARKER_STROKE = new BasicStroke(1f);
	private static final BasicStroke LINE_STROKE = new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
	private static final BasicStroke DASH_STROKE = new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f, new float[] {4f, 4f}, 0f);
	private static Font emojiFont;

	private CombatSession session;
	private int sampleCount = -1;
	private int markerCount = -1;
	private int expectedDpsTenths = -1;

	DpsChartPanel()
	{
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setPreferredSize(new Dimension(0, 100));
		setMinimumSize(new Dimension(0, 100));
	}

	void setSessionIfChanged(CombatSession session)
	{
		int nextSamples = session == null ? 0 : session.getSamples().size();
		int nextMarkers = 0;
		int nextExpected = 0;
		if (session != null)
		{
			nextMarkers = session.getAttackMarkers().size() + session.getPrayerMarkers().size();
			ExpectedDpsEstimate expected = session.getExpectedDps();
			if (expected != null)
			{
				nextExpected = (int) Math.round(expected.getDps() * 10);
			}
		}

		if (session == this.session && nextSamples == sampleCount && nextMarkers == markerCount
			&& nextExpected == expectedDpsTenths)
		{
			return;
		}

		this.session = session;
		sampleCount = nextSamples;
		markerCount = nextMarkers;
		expectedDpsTenths = nextExpected;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		super.paintComponent(graphics);
		Graphics2D g = (Graphics2D) graphics;
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		int w = getWidth();
		int h = getHeight();
		int chartW = w - PAD_LEFT - PAD_RIGHT;
		int chartH = h - PAD_TOP - PAD_BOTTOM;

		g.setColor(ColorScheme.DARKER_GRAY_COLOR);
		g.fillRect(0, 0, w, h);

		if (session == null)
		{
			drawPlaceholder(g, h, "DPS chart appears during fights");
			return;
		}

		List<DpsSample> samples = session.getSamples();
		long chartDurationMs = session.getChartDurationMs();

		if (samples.size() < 2 || chartDurationMs <= 0)
		{
			drawPlaceholder(g, h, "Chart starts after warmup period");
			return;
		}

		double maxDps = samples.stream().mapToDouble(DpsSample::getRollingDps).max().orElse(1);
		if (maxDps <= 0)
		{
			maxDps = 1;
		}
		maxDps *= 1.1;

		drawGrid(g, chartW, chartH, maxDps, chartDurationMs);
		drawLine(g, chartW, chartH, maxDps, chartDurationMs, samples);
		drawExpectedDpsLine(g, chartW, chartH, maxDps);
		int markerY = PAD_TOP + chartH + 2;
		markerY = drawAttackMarkers(g, chartW, chartH, chartDurationMs, markerY);
		drawPrayerMarkers(g, chartW, chartH, chartDurationMs, markerY);
		drawLabels(g, chartH, maxDps, chartDurationMs);
	}

	private void drawPlaceholder(Graphics2D g, int h, String text)
	{
		g.setColor(LABEL_COLOR);
		g.setFont(g.getFont().deriveFont(10f));
		g.drawString(text, PAD_LEFT, h / 2);
	}

	private void drawGrid(Graphics2D g, int chartW, int chartH, double maxDps, long chartDurationMs)
	{
		g.setColor(GRID_COLOR);
		g.setStroke(MARKER_STROKE);

		for (int i = 0; i <= 2; i++)
		{
			int y = PAD_TOP + (chartH * i / 2);
			g.drawLine(PAD_LEFT, y, PAD_LEFT + chartW, y);
		}

		for (int i = 0; i <= 3; i++)
		{
			int x = PAD_LEFT + (chartW * i / 3);
			g.drawLine(x, PAD_TOP, x, PAD_TOP + chartH);
		}

		g.setColor(LABEL_COLOR);
		g.setFont(g.getFont().deriveFont(9f));
		g.drawString("0", 4, PAD_TOP + chartH + 4);
		g.drawString(formatTime(chartDurationMs), PAD_LEFT + chartW - 20, PAD_TOP + chartH + 14);
	}

	private void drawLine(Graphics2D g, int chartW, int chartH, double maxDps, long chartDurationMs, List<DpsSample> samples)
	{
		g.setColor(LINE_COLOR);
		g.setStroke(LINE_STROKE);

		long chartStartMs = session.getChartWarmupMs();
		int prevX = -1;
		int prevY = -1;

		for (DpsSample sample : samples)
		{
			long relativeMs = sample.getElapsedMs() - chartStartMs;
			int x = PAD_LEFT + (int) (chartW * relativeMs / (double) chartDurationMs);
			int y = PAD_TOP + chartH - (int) (chartH * sample.getRollingDps() / maxDps);
			y = Math.max(PAD_TOP, Math.min(PAD_TOP + chartH, y));

			if (prevX >= 0)
			{
				g.drawLine(prevX, prevY, x, y);
			}
			prevX = x;
			prevY = y;
		}
	}

	private void drawExpectedDpsLine(Graphics2D g, int chartW, int chartH, double maxDps)
	{
		ExpectedDpsEstimate estimate = session.getExpectedDps();
		if (estimate == null || estimate.getDps() <= 0)
		{
			return;
		}

		int y = PAD_TOP + chartH - (int) (chartH * estimate.getDps() / maxDps);
		y = Math.max(PAD_TOP, Math.min(PAD_TOP + chartH, y));

		g.setColor(EXPECTED_LINE_COLOR);
		g.setStroke(DASH_STROKE);
		g.drawLine(PAD_LEFT, y, PAD_LEFT + chartW, y);
	}

	private int drawAttackMarkers(Graphics2D g, int chartW, int chartH, long chartDurationMs, int startY)
	{
		List<AttackMarker> markers = session.getAttackMarkers();
		if (markers.isEmpty())
		{
			return startY;
		}

		long chartStartMs = session.getChartWarmupMs();
		Map<Integer, Integer> stackAtX = new HashMap<>();
		int maxStack = 0;

		g.setFont(getEmojiFont(g, 12f));
		FontMetrics fm = g.getFontMetrics();

		for (AttackMarker marker : markers)
		{
			long relativeMs = marker.getElapsedMs() - chartStartMs;
			if (marker.getElapsedMs() < chartStartMs)
			{
				relativeMs = 0;
			}
			else if (relativeMs > chartDurationMs)
			{
				continue;
			}

			int x = PAD_LEFT + (int) (chartW * relativeMs / (double) chartDurationMs);
			int stack = stackAtX.merge(x, 1, Integer::sum) - 1;
			maxStack = Math.max(maxStack, stack + 1);
			int y = startY + stack * (EMOJI_MARKER_HEIGHT + 1);

			g.setColor(marker.getLineColor());
			g.setStroke(MARKER_STROKE);
			g.drawLine(x, PAD_TOP + chartH, x, y + fm.getAscent() - 2);

			String symbol = marker.getSymbol();
			g.setColor(Color.WHITE);
			g.drawString(symbol, x - fm.stringWidth(symbol) / 2, y + fm.getAscent());
		}

		return startY + maxStack * (EMOJI_MARKER_HEIGHT + 1);
	}

	private void drawPrayerMarkers(Graphics2D g, int chartW, int chartH, long chartDurationMs, int startY)
	{
		List<PrayerMarker> markers = session.getPrayerMarkers();
		if (markers.isEmpty())
		{
			return;
		}

		long chartStartMs = session.getChartWarmupMs();
		int markerY = startY;
		Map<Integer, Integer> stackAtX = new HashMap<>();

		g.setFont(g.getFont().deriveFont(Font.BOLD, 7f));
		FontMetrics fm = g.getFontMetrics();

		for (PrayerMarker marker : markers)
		{
			long relativeMs = marker.getElapsedMs() - chartStartMs;
			if (marker.getElapsedMs() < chartStartMs)
			{
				relativeMs = 0;
			}
			else if (relativeMs > chartDurationMs)
			{
				continue;
			}

			int x = PAD_LEFT + (int) (chartW * relativeMs / (double) chartDurationMs);
			int stack = stackAtX.merge(x, 1, Integer::sum) - 1;
			int y = markerY + stack * (MARKER_SIZE + 1);

			g.setColor(marker.getColor());
			g.fillOval(x - MARKER_SIZE / 2, y, MARKER_SIZE, MARKER_SIZE);
			g.setColor(Color.BLACK);
			g.drawOval(x - MARKER_SIZE / 2, y, MARKER_SIZE, MARKER_SIZE);

			g.setColor(Color.WHITE);
			int textX = x - fm.stringWidth(marker.getLabel()) / 2;
			int textY = y + ((MARKER_SIZE + fm.getAscent()) / 2) - 1;
			g.drawString(marker.getLabel(), textX, textY);

			g.setColor(marker.getColor().darker());
			g.setStroke(MARKER_STROKE);
			g.drawLine(x, PAD_TOP + chartH, x, y);
		}
	}

	private void drawLabels(Graphics2D g, int chartH, double maxDps, long chartDurationMs)
	{
		g.setFont(g.getFont().deriveFont(Font.PLAIN, 9f));
		g.setColor(LABEL_COLOR);
		FontMetrics fm = g.getFontMetrics();
		String topLabel = DPS_FORMAT.format(maxDps / 1.1);
		g.drawString(topLabel, 2, PAD_TOP + fm.getAscent());
	}

	private static Font getEmojiFont(Graphics2D g, float size)
	{
		if (emojiFont != null)
		{
			return emojiFont;
		}

		Font emoji = new Font("Segoe UI Emoji", Font.PLAIN, (int) size);
		if (emoji.canDisplayUpTo("\uD83D\uDCA5") == -1)
		{
			emojiFont = emoji;
			return emojiFont;
		}

		Font fallback = new Font("Dialog", Font.PLAIN, (int) size);
		if (fallback.canDisplayUpTo("\uD83D\uDCA5") == -1)
		{
			emojiFont = fallback;
			return emojiFont;
		}

		emojiFont = g.getFont().deriveFont(size);
		return emojiFont;
	}

	private static String formatTime(long ms)
	{
		long sec = ms / 1000;
		if (sec >= 60)
		{
			return (sec / 60) + "m";
		}
		return sec + "s";
	}
}

package com.spoopdps;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.text.DecimalFormat;
import net.runelite.client.util.QuantityFormatter;

final class DpsMeterRenderer
{
	private static final DecimalFormat DPS_FORMAT = new DecimalFormat("#0.0");
	private static final DecimalFormat PERCENT_FORMAT = new DecimalFormat("#0");
	private static final long PEAK_LINE_DELAY_MS = 5000;

	private static final Color EXPECTED_COLOR = new Color(100, 180, 255);
	private static final Color EXPECTED_DIM = new Color(100, 180, 255, 150);
	private static final Color PEAK_COLOR = new Color(255, 70, 70);
	private static final Color PEAK_DIM = new Color(255, 70, 70, 150);
	private static final Color ACTIVE_FILL = new Color(198, 40, 40);
	private static final Color NEUTRAL_FILL = new Color(110, 110, 110);
	private static final Color BAR_BG = new Color(25, 25, 25);
	private static final Color BAR_BORDER = new Color(55, 55, 55);
	private static final Color ACTIVE_PANEL = new Color(0, 0, 0, 170);
	private static final Color NEUTRAL_PANEL = new Color(0, 0, 0, 130);
	private static final Color PB_COLOR = new Color(80, 220, 120);
	private static final Color GOLD = new Color(255, 200, 80);
	private static final Color GOLD_DIM = new Color(180, 150, 80);
	private static final Color NAME_IDLE = new Color(200, 200, 200);
	private static final Color LABEL_IDLE = new Color(210, 210, 210);
	private static final Color SUBTITLE_COLOR = new Color(160, 160, 160);
	private static final Color WHIFF_COLOR = new Color(180, 180, 180);
	private static final Color WHIFF_DIM = new Color(130, 130, 130);
	private static final Color TEXT_SHADOW = new Color(0, 0, 0, 200);
	private static final BasicStroke STROKE_1 = new BasicStroke(1f);
	private static final BasicStroke STROKE_1_5 = new BasicStroke(1.5f);
	private static final BasicStroke STROKE_2 = new BasicStroke(2f);
	private static final Font[] BOLD_FONTS = new Font[16];
	private static final Font[] PLAIN_FONTS = new Font[16];
	private static final MeterLayout LAYOUT_THIN = new MeterLayout(200, 18, 0, 3, 11, 10, 10, 8, 4, true, false, false, 1.5f, true);
	private static final MeterLayout LAYOUT_MEGA = new MeterLayout(100, 8, 0, 2, 0, 9, 8, 8, 3, false, false, false, 1f, false);
	private static final MeterLayout LAYOUT_BIG = new MeterLayout(200, 22, 78, 4, 12, 10, 11, 9, 5, true, true, true, 2f, false);

	static final int ROW_GAP = 1;
	static final int BOSS_HEADER_HEIGHT = 18;

	private DpsMeterRenderer()
	{
	}

	static Dimension drawBossHeader(Graphics2D graphics, int originX, int originY, String bossName,
		boolean inCombat, int width)
	{
		int padding = 4;
		graphics.setFont(font(Font.BOLD, 11));
		FontMetrics metrics = graphics.getFontMetrics();
		int totalWidth = Math.max(width, metrics.stringWidth(bossName) + padding * 2);
		int totalHeight = BOSS_HEADER_HEIGHT + padding;

		graphics.translate(originX, originY);

		graphics.setColor(inCombat ? ACTIVE_PANEL : NEUTRAL_PANEL);
		graphics.fillRoundRect(0, 0, totalWidth, totalHeight, 4, 4);

		graphics.setColor(inCombat ? GOLD : GOLD_DIM);
		int textY = padding + metrics.getAscent();
		graphics.drawString(bossName, padding, textY);

		graphics.translate(-originX, -originY);
		return new Dimension(totalWidth, totalHeight);
	}

	static Dimension drawMeter(Graphics2D graphics, int originX, int originY, DpsMeterSnapshot snapshot,
		SpoopDpsConfig config, String nameLabel, MeterSize meterSize, boolean showLuckStats)
	{
		return drawMeter(graphics, originX, originY, snapshot, config, nameLabel, meterSize, showLuckStats, null, 0);
	}

	static Dimension drawMeter(Graphics2D graphics, int originX, int originY, DpsMeterSnapshot snapshot,
		SpoopDpsConfig config, String nameLabel, MeterSize meterSize, boolean showLuckStats,
		Color playerColor, double sharedScaleMax)
	{
		MeterLayout layout = layoutFor(meterSize);
		boolean inCombat = snapshot.isInCombat();
		boolean showSubtitle = shouldShowSubtitle(snapshot, config, meterSize);
		boolean hasName = nameLabel != null && !nameLabel.isEmpty();
		boolean inlineLabels = layout.inlineBarLabels;
		int headerHeight = (showSubtitle ? layout.subtitleHeight : 0)
			+ (hasName && !inlineLabels ? layout.subtitleHeight : 0);

		double scaleMax = sharedScaleMax > 0
			? sharedScaleMax
			: resolveScaleMax(snapshot.getDps(), snapshot.getExpectedDps(), snapshot.getPeakDps());
		boolean drawLuck = showLuckStats && layout.showLuckStats && snapshot.getAttackCount() > 0;
		int totalWidth = layout.barWidth + (drawLuck ? layout.statsWidth : 0) + layout.padding * 2;
		int totalHeight = layout.barHeight + layout.padding * 2 + headerHeight;

		graphics.translate(originX, originY);

		graphics.setColor(inCombat ? ACTIVE_PANEL : NEUTRAL_PANEL);
		graphics.fillRoundRect(0, 0, totalWidth, totalHeight, layout.cornerRadius, layout.cornerRadius);

		int barX = layout.padding;
		int headerY = layout.padding;
		if (hasName && !inlineLabels)
		{
			graphics.setFont(font(Font.BOLD, layout.nameFontSize));
			Color headerColor = playerColor != null
				? PartyMemberColors.labelText(playerColor, inCombat)
				: (inCombat ? Color.WHITE : NAME_IDLE);
			graphics.setColor(headerColor);
			String header = nameLabel;
			if (snapshot.hasDamagePercent())
			{
				header = nameLabel + "  " + PERCENT_FORMAT.format(snapshot.getDamagePercent()) + "%";
			}
			graphics.drawString(header, barX, headerY + layout.subtitleHeight - 2);
			headerY += layout.subtitleHeight;
		}
		if (showSubtitle)
		{
			graphics.setFont(font(Font.PLAIN, layout.nameFontSize));
			graphics.setColor(SUBTITLE_COLOR);
			graphics.drawString(snapshot.getSubtitle(), barX, headerY + layout.subtitleHeight - 2);
		}

		int barY = layout.padding + headerHeight;

		graphics.setColor(BAR_BG);
		graphics.fillRect(barX, barY, layout.barWidth, layout.barHeight);
		graphics.setColor(BAR_BORDER);
		graphics.drawRect(barX, barY, layout.barWidth, layout.barHeight);

		if (snapshot.getDps() > 0.05)
		{
			double fillRatio = Math.min(1.0, snapshot.getDps() / scaleMax);
			int fillWidth = (int) Math.round(fillRatio * (layout.barWidth - 2));
			fillWidth = Math.max(0, Math.min(layout.barWidth - 2, fillWidth));
			if (fillWidth > 0)
			{
				Color fill = playerColor != null
					? PartyMemberColors.barFill(playerColor, inCombat)
					: (inCombat ? ACTIVE_FILL : NEUTRAL_FILL);
				graphics.setColor(fill);
				graphics.fillRect(barX + 1, barY + 1, fillWidth, layout.barHeight - 2);
			}
		}

		if (config.showExpectedDps() && snapshot.getExpectedDps() > 0
			&& (layout.showExpectedLine || sharedScaleMax > 0))
		{
			drawVerticalMarker(graphics, barX, barY, layout.barWidth, layout.barHeight, snapshot.getExpectedDps(), scaleMax,
				inCombat ? EXPECTED_COLOR : EXPECTED_DIM, layout.markerStroke);
		}

		if (layout.showPeakLine && shouldShowPeakLine(snapshot))
		{
			drawVerticalMarker(graphics, barX, barY, layout.barWidth, layout.barHeight, snapshot.getPeakDps(), scaleMax,
				inCombat ? PEAK_COLOR : PEAK_DIM, layout.markerStroke);
		}

		if (inlineLabels)
		{
			Color nameColor = playerColor != null
				? PartyMemberColors.labelText(playerColor, inCombat)
				: (inCombat ? Color.WHITE : LABEL_IDLE);
			drawInlineBarLabels(graphics, barX, barY, layout, nameLabel, snapshot, inCombat, nameColor);
		}
		else
		{
			drawDpsLabel(graphics, barX, barY, layout, snapshot, inCombat);

			if (snapshot.isAbovePersonalBest())
			{
				graphics.setFont(font(Font.BOLD, layout.statsFontSize));
				graphics.setColor(PB_COLOR);
				FontMetrics metrics = graphics.getFontMetrics();
				int pbX = barX + layout.barWidth - metrics.stringWidth("PB!") - 4;
				int pbY = barY + ((layout.barHeight - metrics.getHeight()) / 2) + metrics.getAscent();
				graphics.drawString("PB!", Math.max(barX + 4, pbX), pbY);
			}
		}

		if (drawLuck)
		{
			drawLuckStats(graphics, barX + layout.barWidth + 4, barY, layout, snapshot, inCombat);
		}

		graphics.translate(-originX, -originY);
		return new Dimension(totalWidth, totalHeight);
	}

	static int estimatedRowHeight(MeterSize meterSize)
	{
		switch (meterSize)
		{
			case MEGA_COMPACT:
				return 12;
			case THIN:
				return 24;
			case BIG:
			default:
				return 30;
		}
	}

	static MeterSize partyRowSize(MeterSize mainSize)
	{
		if (mainSize == MeterSize.MEGA_COMPACT)
		{
			return MeterSize.MEGA_COMPACT;
		}
		return MeterSize.THIN;
	}

	private static boolean shouldShowSubtitle(DpsMeterSnapshot snapshot, SpoopDpsConfig config, MeterSize meterSize)
	{
		if (meterSize != MeterSize.BIG)
		{
			return false;
		}

		if (snapshot.getSubtitle() == null || snapshot.getSubtitle().isEmpty())
		{
			return false;
		}

		if (snapshot.isInCombat())
		{
			return config.showTargetNameOnMeter();
		}

		return true;
	}

	private static boolean shouldShowPeakLine(DpsMeterSnapshot snapshot)
	{
		if (snapshot.getPeakDps() <= 0)
		{
			return false;
		}
		return !snapshot.isInCombat() || snapshot.getFightElapsedMs() >= PEAK_LINE_DELAY_MS;
	}

	private static void drawLuckStats(Graphics2D graphics, int x, int barY, MeterLayout layout,
		DpsMeterSnapshot snapshot, boolean inCombat)
	{
		graphics.setFont(font(Font.PLAIN, layout.statsFontSize));
		Color boomColor = inCombat ? GOLD : GOLD_DIM;
		Color whiffColor = inCombat ? WHIFF_COLOR : WHIFF_DIM;

		graphics.setColor(boomColor);
		graphics.drawString("Boom " + snapshot.getBoomCount(), x, barY + 9);
		graphics.setColor(whiffColor);
		graphics.drawString("Miss " + snapshot.getWhiffCount(), x, barY + 19);
	}

	private static void drawVerticalMarker(Graphics2D graphics, int barX, int barY, int barWidth, int barHeight,
		double value, double scaleMax, Color color, float strokeWidth)
	{
		int lineX = barX + (int) Math.round((value / scaleMax) * barWidth);
		lineX = Math.max(barX + 1, Math.min(barX + barWidth - 1, lineX));
		graphics.setColor(color);
		graphics.setStroke(strokeFor(strokeWidth));
		graphics.drawLine(lineX, barY + 1, lineX, barY + barHeight - 1);
	}

	private static void drawInlineBarLabels(Graphics2D graphics, int barX, int barY, MeterLayout layout,
		String nameLabel, DpsMeterSnapshot snapshot, boolean inCombat, Color nameColor)
	{
		graphics.setFont(font(Font.BOLD, layout.dpsFontSize));
		FontMetrics metrics = graphics.getFontMetrics();
		int textY = barY + ((layout.barHeight - metrics.getHeight()) / 2) + metrics.getAscent();
		Color dpsColor = inCombat ? Color.WHITE : LABEL_IDLE;

		if (nameLabel != null && !nameLabel.isEmpty())
		{
			String leftText = nameLabel;
			if (snapshot.hasDamagePercent())
			{
				leftText = nameLabel + "  " + PERCENT_FORMAT.format(snapshot.getDamagePercent()) + "%";
			}
			drawTextWithShadow(graphics, leftText, barX + 5, textY, nameColor);
		}

		String dpsText = formatDpsLabel(snapshot);
		int dpsX = barX + layout.barWidth - metrics.stringWidth(dpsText) - 5;
		drawTextWithShadow(graphics, dpsText, dpsX, textY, dpsColor);

		if (snapshot.isAbovePersonalBest() && snapshot.getDps() > 0.05)
		{
			graphics.setFont(font(Font.BOLD, layout.statsFontSize));
			metrics = graphics.getFontMetrics();
			int pbX = dpsX - metrics.stringWidth("PB! ") - 2;
			graphics.setColor(PB_COLOR);
			graphics.drawString("PB!", Math.max(barX + 5, pbX), textY);
		}
	}

	private static void drawTextWithShadow(Graphics2D graphics, String text, int x, int y, Color color)
	{
		graphics.setColor(TEXT_SHADOW);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}

	private static void drawDpsLabel(Graphics2D graphics, int barX, int barY, MeterLayout layout,
		DpsMeterSnapshot snapshot, boolean inCombat)
	{
		graphics.setFont(font(Font.BOLD, layout.dpsFontSize));
		FontMetrics metrics = graphics.getFontMetrics();
		String text = formatDpsLabel(snapshot);
		int textX = barX + 4;
		int textY = barY + ((layout.barHeight - metrics.getHeight()) / 2) + metrics.getAscent();

		if (layout.barHeight >= 14)
		{
			graphics.setColor(TEXT_SHADOW);
			graphics.drawString(text, textX + 1, textY + 1);
		}
		graphics.setColor(inCombat ? Color.WHITE : LABEL_IDLE);
		graphics.drawString(text, textX, textY);
	}

	private static String formatDpsLabel(DpsMeterSnapshot snapshot)
	{
		if (snapshot.getDps() <= 0.05)
		{
			return "Idle";
		}

		String text = DPS_FORMAT.format(snapshot.getDps());
		if (snapshot.getTotalDamage() > 0)
		{
			text += " (" + QuantityFormatter.formatNumber(snapshot.getTotalDamage()) + ")";
		}
		return text;
	}

	private static double resolveScaleMax(double displayDps, double expectedDps, double peakDps)
	{
		double high = Math.max(displayDps, Math.max(expectedDps, peakDps));
		return Math.max(high * 1.1, 1.0);
	}

	private static MeterLayout layoutFor(MeterSize size)
	{
		switch (size)
		{
			case THIN:
				return LAYOUT_THIN;
			case MEGA_COMPACT:
				return LAYOUT_MEGA;
			case BIG:
			default:
				return LAYOUT_BIG;
		}
	}

	private static Font font(int style, int size)
	{
		Font[] table = style == Font.BOLD ? BOLD_FONTS : PLAIN_FONTS;
		int index = Math.max(1, Math.min(size, table.length - 1));
		Font cached = table[index];
		if (cached == null)
		{
			cached = new Font(Font.SANS_SERIF, style, index);
			table[index] = cached;
		}
		return cached;
	}

	private static BasicStroke strokeFor(float width)
	{
		if (width >= 1.75f)
		{
			return STROKE_2;
		}
		if (width >= 1.25f)
		{
			return STROKE_1_5;
		}
		return STROKE_1;
	}

	private static final class MeterLayout
	{
		private final int barWidth;
		private final int barHeight;
		private final int statsWidth;
