@Builder
class DpsMeterSnapshot
{
	String subtitle;
	double dps;
	double expectedDps;
	double peakDps;
	long fightElapsedMs;
	boolean inCombat;
	double boomPercent;
	double whiffPercent;
	@Builder.Default
	int boomCount = 0;
	@Builder.Default
	int whiffCount = 0;
	int attackCount;
	@Builder.Default
	double damagePercent = -1;
	@Builder.Default
	boolean abovePersonalBest = false;
	@Builder.Default
	int totalDamage = 0;

	boolean hasDamagePercent()
	{
		return damagePercent >= 0;
	}

	static DpsMeterSnapshot fromSession(CombatSession session, boolean inCombat, SpoopDpsConfig config)
	{
		if (session == null)
		{
			return DpsMeterSnapshot.builder()
				.dps(0)
				.inCombat(false)
				.build();
		}

		String subtitle = null;
		if (!inCombat)
		{
			subtitle = session.getHistoryLabel();
		}
		else if (config.showTargetNameOnMeter() && config.meterSize() == MeterSize.BIG)
		{
			subtitle = session.getHistoryLabel();
		}

		ExpectedDpsEstimate expected = session.getExpectedDps();
		return DpsMeterSnapshot.builder()
			.subtitle(subtitle)
			.dps(session.getDps())
			.expectedDps(expected != null ? expected.getDps() : 0)
			.peakDps(session.getPeakRollingDps())
			.fightElapsedMs(session.getElapsedMs())
			.inCombat(inCombat)
			.boomPercent(session.getBoomPercent())
			.whiffPercent(session.getWhiffPercent())
			.boomCount(session.getBoomCount())
			.whiffCount(session.getWhiffCount())
			.attackCount(session.getAttackCount())
			.totalDamage(session.getTotalDamage())
			.build();
	}
