package com.spoopdps;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.NPCComposition;
import net.runelite.api.Prayer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

@Singleton
class ExpectedDpsCalculator
{
	private static final double TICK_SECONDS = 0.6;

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	ExpectedDpsEstimate calculate(NPC target)
	{
		if (target == null || client.getLocalPlayer() == null)
		{
			return null;
		}

		EquipmentStats equipment = loadEquipmentStats();
		if (equipment == null)
		{
			return null;
		}

		NPCComposition composition = target.getTransformedComposition();
		if (composition == null)
		{
			composition = target.getComposition();
		}

		int[] npcStats = composition != null ? composition.getStats() : null;
		int defenceLevel = npcStats != null && npcStats.length > NPCComposition.STAT_DEFENCE
			? npcStats[NPCComposition.STAT_DEFENCE]
			: Math.max(1, target.getCombatLevel());

		if (equipment.isRanged())
		{
			return calculateRanged(equipment, defenceLevel);
		}

		if (equipment.isMagic())
		{
			return null;
		}

		return calculateMelee(equipment, defenceLevel);
	}

	private ExpectedDpsEstimate calculateMelee(EquipmentStats equipment, int defenceLevel)
	{
		AttackType attackType = equipment.getBestMeleeAttackType();
		int attackBonus = equipment.getMeleeAttackBonus(attackType);
		int defenceBonus = 0;

		double attackPrayer = 1.0;
		double strengthPrayer = 1.0;
		if (client.isPrayerActive(Prayer.PIETY))
		{
			attackPrayer = 1.20;
			strengthPrayer = 1.23;
		}
		else if (client.isPrayerActive(Prayer.CHIVALRY))
		{
			attackPrayer = 1.15;
			strengthPrayer = 1.18;
		}
		else if (client.isPrayerActive(Prayer.ULTIMATE_STRENGTH))
		{
			strengthPrayer = 1.15;
		}
		else if (client.isPrayerActive(Prayer.SUPERHUMAN_STRENGTH))
		{
			strengthPrayer = 1.10;
		}
		else if (client.isPrayerActive(Prayer.BURST_OF_STRENGTH))
		{
			strengthPrayer = 1.05;
		}

		if (client.isPrayerActive(Prayer.CLARITY_OF_THOUGHT))
		{
			attackPrayer = Math.max(attackPrayer, 1.05);
		}
		else if (client.isPrayerActive(Prayer.IMPROVED_REFLEXES))
		{
			attackPrayer = Math.max(attackPrayer, 1.10);
		}
		else if (client.isPrayerActive(Prayer.INCREDIBLE_REFLEXES))
		{
			attackPrayer = Math.max(attackPrayer, 1.15);
		}

		int effectiveStrength = effectiveLevel(client.getBoostedSkillLevel(Skill.STRENGTH), strengthPrayer, 3);
		int effectiveAttack = effectiveLevel(client.getBoostedSkillLevel(Skill.ATTACK), attackPrayer, 3);

		int maxHit = maxHit(effectiveStrength, equipment.strengthBonus);
		long attackRoll = (long) effectiveAttack * (attackBonus + 64);
		long defenceRoll = (long) (defenceLevel + 9) * (defenceBonus + 64);
		double hitChance = hitChance(attackRoll, defenceRoll);
		double avgDamage = averageDamage(maxHit, hitChance);
		double dps = avgDamage / (equipment.weaponSpeedTicks * TICK_SECONDS);

		return new ExpectedDpsEstimate(
			dps,
			maxHit,
			hitChance,
			ExpectedDpsEstimate.CombatStyle.MELEE,
			attackType.label,
			true
		);
	}

	private ExpectedDpsEstimate calculateRanged(EquipmentStats equipment, int defenceLevel)
	{
		int defenceBonus = 0;

		double attackPrayer = 1.0;
		double strengthPrayer = 1.0;
		if (client.isPrayerActive(Prayer.RIGOUR))
		{
			attackPrayer = 1.20;
			strengthPrayer = 1.23;
		}
		else if (client.isPrayerActive(Prayer.EAGLE_EYE))
		{
			attackPrayer = 1.15;
			strengthPrayer = 1.15;
		}
		else if (client.isPrayerActive(Prayer.HAWK_EYE))
		{
			attackPrayer = 1.10;
			strengthPrayer = 1.10;
		}
		else if (client.isPrayerActive(Prayer.SHARP_EYE))
		{
			attackPrayer = 1.05;
			strengthPrayer = 1.05;
		}

		int effectiveRanged = effectiveLevel(client.getBoostedSkillLevel(Skill.RANGED), strengthPrayer, 3);
		int effectiveAttack = effectiveLevel(client.getBoostedSkillLevel(Skill.RANGED), attackPrayer, 3);

		int maxHit = maxHit(effectiveRanged, equipment.rangedStrengthBonus);
		long attackRoll = (long) effectiveAttack * (equipment.rangeAttackBonus + 64);
		long defenceRoll = (long) (defenceLevel + 9) * (defenceBonus + 64);
		double hitChance = hitChance(attackRoll, defenceRoll);
		double avgDamage = averageDamage(maxHit, hitChance);
		double dps = avgDamage / (equipment.weaponSpeedTicks * TICK_SECONDS);

		return new ExpectedDpsEstimate(
			dps,
			maxHit,
			hitChance,
			ExpectedDpsEstimate.CombatStyle.RANGED,
			"Ranged",
			true
		);
	}

	private static int effectiveLevel(int level, double prayerMultiplier, int styleBonus)
	{
		return (int) Math.floor(Math.floor(level * prayerMultiplier) + styleBonus + 8);
	}

	private static int maxHit(int effectiveStrength, int strengthBonus)
	{
		return (int) Math.floor(0.5 + ((effectiveStrength * (strengthBonus + 64)) / 640.0));
	}

	private static double hitChance(long attackRoll, long defenceRoll)
	{
		if (attackRoll > defenceRoll)
		{
			return 1.0 - ((defenceRoll + 2.0) / (2.0 * (attackRoll + 1.0)));
		}
		return attackRoll / (2.0 * (defenceRoll + 1.0));
	}

	private static double averageDamage(int maxHit, double hitChance)
	{
		if (maxHit <= 0)
		{
			return 0;
		}
		return hitChance * ((maxHit / 2.0) + (1.0 / (maxHit + 1.0)));
	}

	private EquipmentStats loadEquipmentStats()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
		{
			return null;
		}

		EquipmentStats stats = new EquipmentStats();
		Item weapon = worn.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null)
		{
			return null;
		}

		for (Item item : worn.getItems())
		{
			if (item == null || item.getId() <= 0)
			{
				continue;
			}

			ItemStats itemStats = itemManager.getItemStats(item.getId());
			if (itemStats == null || itemStats.getEquipment() == null)
			{
				continue;
			}

			ItemEquipmentStats eq = itemStats.getEquipment();
			stats.stabAttackBonus += eq.getAstab();
			stats.slashAttackBonus += eq.getAslash();
			stats.crushAttackBonus += eq.getAcrush();
			stats.rangeAttackBonus += eq.getArange();
			stats.magicAttackBonus += eq.getAmagic();
			stats.strengthBonus += eq.getStr();
			stats.rangedStrengthBonus += eq.getRstr();

			if (item.getId() == weapon.getId() && eq.getAspeed() > 0)
			{
				stats.weaponSpeedTicks = eq.getAspeed();
			}
		}

		return stats;
	}

	private static final class EquipmentStats
	{
		private int stabAttackBonus;
		private int slashAttackBonus;
		private int crushAttackBonus;
		private int rangeAttackBonus;
		private int magicAttackBonus;
		private int strengthBonus;
		private int rangedStrengthBonus;
		private int weaponSpeedTicks = 4;

		private boolean isRanged()
		{
			return rangeAttackBonus > Math.max(stabAttackBonus, Math.max(slashAttackBonus, crushAttackBonus))
				&& rangedStrengthBonus > 0;
		}

		private boolean isMagic()
		{
			return magicAttackBonus > Math.max(stabAttackBonus, Math.max(slashAttackBonus, crushAttackBonus))
				&& magicAttackBonus > rangeAttackBonus;
		}

		private AttackType getBestMeleeAttackType()
		{
			if (stabAttackBonus >= slashAttackBonus && stabAttackBonus >= crushAttackBonus)
			{
				return AttackType.STAB;
			}
			if (slashAttackBonus >= crushAttackBonus)
			{
				return AttackType.SLASH;
			}
			return AttackType.CRUSH;
		}

		private int getMeleeAttackBonus(AttackType attackType)
		{
			switch (attackType)
			{
				case STAB:
					return stabAttackBonus;
				case SLASH:
					return slashAttackBonus;
				default:
					return crushAttackBonus;
			}
		}
	}

	private enum AttackType
	{
		STAB("Stab"),
		SLASH("Slash"),
		CRUSH("Crush");

		private final String label;

		AttackType(String label)
		{
			this.label = label;
		}
	}
}

