package com.spoopdps;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;

@Singleton
class PartyDamageTracker
{
	@Inject
	private Client client;

	@Inject
	private Provider<CombatTracker> combatTracker;

	@Inject
	private Provider<PartyDpsTracker> partyDpsTracker;

	@Inject
	private PersonalBestStore personalBestStore;

	private int othersDamage;
	private BossRecap lastBossRecap;

	int getOthersDamageForDisplay()
	{
		return othersDamage;
	}

	void reset()
	{
		othersDamage = 0;
	}

	void clearRecap()
	{
		lastBossRecap = null;
	}

	BossRecap getLastBossRecap()
	{
		return lastBossRecap;
	}

	void recordOthersDamage(NPC npc, int amount)
	{
		if (amount <= 0 || !BossNpcIds.isBoss(npc.getId()) || !isRelevantBossTarget(npc))
		{
			return;
		}

		othersDamage += amount;
	}

	BossRecap onCombatEnd(CombatSession session, boolean newPersonalBest)
	{
		if (session == null || !session.isBossFight())
		{
			reset();
			return null;
		}

		lastBossRecap = buildRecap(session, newPersonalBest);
		reset();
		return lastBossRecap;
	}

	int getPartyTotalDamage(CombatSession session, List<PartyMemberDpsState> remoteMembers)
	{
		int total = session != null ? session.getTotalDamage() : 0;
		int namedRemote = namedRemoteDamage(remoteMembers);
		return total + namedRemote + unaccountedOthersDamage(namedRemote);
	}

	private int namedRemoteDamage(List<PartyMemberDpsState> remoteMembers)
	{
		int namedRemote = 0;
		if (remoteMembers == null)
		{
			return 0;
		}

		for (PartyMemberDpsState member : remoteMembers)
		{
			if (member.getTotalDamage() > 0)
			{
				namedRemote += member.getTotalDamage();
			}
		}
		return namedRemote;
	}

	private int unaccountedOthersDamage(int namedRemoteDamage)
	{
		return Math.max(0, othersDamage - namedRemoteDamage);
	}

	double getDamagePercent(int damage, int partyTotal)
	{
		if (partyTotal <= 0 || damage <= 0)
		{
			return 0;
		}
		return (damage * 100.0) / partyTotal;
	}

	private BossRecap buildRecap(CombatSession session, boolean newPersonalBest)
	{
		TargetStats primary = session.getPrimaryTarget();
		String bossName = primary != null ? primary.getName() : session.getHistoryLabel();
		int bossLevel = primary != null ? primary.getCombatLevel() : 0;

		Player player = client.getLocalPlayer();
		String localName = player != null ? player.getName() : "You";

		List<PartyMemberDpsState> remoteMembers = partyDpsTracker.get().getDisplayedPartyMembers();
		int namedRemote = namedRemoteDamage(remoteMembers);
		int unaccounted = unaccountedOthersDamage(namedRemote);
		int partyTotal = session.getTotalDamage() + namedRemote + unaccounted;

		Map<String, BossRecap.BossRecapMember> memberMap = new LinkedHashMap<>();
		if (session.getTotalDamage() > 0)
		{
			memberMap.put(localName, new BossRecap.BossRecapMember(
				localName, session.getDps(), session.getTotalDamage(),
				getDamagePercent(session.getTotalDamage(), partyTotal), true));
		}

		for (PartyMemberDpsState remote : remoteMembers)
		{
			if (remote.getTotalDamage() <= 0)
			{
				continue;
			}

			memberMap.putIfAbsent(remote.getDisplayName(), new BossRecap.BossRecapMember(
				remote.getDisplayName(),
				remote.getSnapshot().getDps(),
				remote.getTotalDamage(),
				getDamagePercent(remote.getTotalDamage(), partyTotal),
				false));
		}

		if (unaccounted > 0)
		{
			memberMap.put("Others", new BossRecap.BossRecapMember(
				"Others", 0, unaccounted, getDamagePercent(unaccounted, partyTotal), false));
		}

		List<BossRecap.BossRecapMember> members = new ArrayList<>(memberMap.values());
		members.sort(Comparator.comparingInt(BossRecap.BossRecapMember::getDamage).reversed());

		Double pb = personalBestStore.getBest(bossName, bossLevel);
		double yourPercent = getDamagePercent(session.getTotalDamage(), partyTotal);

		return new BossRecap(
			bossName,
			bossLevel,
			session.getFormattedDuration(),
			session.getDps(),
			pb != null ? pb : 0,
			newPersonalBest,
			session.getTotalDamage(),
			yourPercent,
			session.getBoomPercent(),
			session.getWhiffPercent(),
			session.getBoomCount(),
			session.getWhiffCount(),
			members
		);
	}

	private boolean isRelevantBossTarget(NPC npc)
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return false;
		}

		if (player.getInteracting() == npc)
		{
			return true;
		}

		CombatSession session = combatTracker.get().getActiveSession();
		return session != null && session.isTracking(npc.getIndex());
	}
}

package com.spoopdps;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import javax.inject.Provider;
import javax.inject.Singleton;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;

@Singleton
class PartyDpsTracker
{
	private static final long STALE_MS = 15000;

	@Inject
	private PartyService partyService;

	@Inject
	private Provider<CombatTracker> combatTracker;

	@Inject
	private SpoopDpsConfig config;

	private final Map<Long, PartyMemberDpsState> remoteMembers = new ConcurrentHashMap<>();

	void clear()
	{
		remoteMembers.clear();
	}

	void broadcastLocalState(SpoopDpsConfig config)
	{
		if (!config.partyDps() || !partyService.isInParty())
		{
			return;
		}

		PartyMember localMember = partyService.getLocalMember();
		if (localMember == null)
		{
			return;
		}

		CombatTracker tracker = combatTracker.get();
		CombatSession session = tracker.getOverlaySession();
		boolean inCombat = tracker.isInCombat();
		ExpectedDpsEstimate expected = session != null ? session.getExpectedDps() : null;

		SpoopDpsPartyUpdate update = new SpoopDpsPartyUpdate(
			session != null ? session.getDps() : 0,
			expected != null ? expected.getDps() : 0,
			session != null ? session.getPeakRollingDps() : 0,
			inCombat,
			session != null ? session.getElapsedMs() : 0,
			session != null ? session.getHistoryLabel() : "",
			session != null ? session.getBoomPercent() : 0,
			session != null ? session.getWhiffPercent() : 0,
			session != null ? session.getAttackCount() : 0,
			session != null ? session.getTotalDamage() : 0,
			session != null && session.isBossFight()
		);
		partyService.send(update);
	}

	void onPartyUpdate(SpoopDpsPartyUpdate update)
	{
		if (!partyService.isInParty())
		{
			return;
		}

		PartyMember localMember = partyService.getLocalMember();
		if (localMember != null && localMember.getMemberId() == update.getMemberId())
		{
			return;
		}

		PartyMember member = partyService.getMemberById(update.getMemberId());
		if (member == null)
		{
			return;
		}

		String name = member.getDisplayName();
		if (name == null)
		{
			return;
		}

		remoteMembers.put(update.getMemberId(), PartyMemberDpsState.fromUpdate(update, name));
	}

	List<PartyMemberDpsState> getDisplayedPartyMembers()
	{
		if (!config.partyDps())
		{
			return List.of();
		}

		return getVisibleRemoteMembers();
	}

	List<PartyMemberDpsState> getVisibleRemoteMembers()
	{
		List<PartyMemberDpsState> members = new ArrayList<>();
		for (PartyMemberDpsState state : remoteMembers.values())
		{
			if (state.isVisible(STALE_MS))
			{
				members.add(state);
			}
		}
		PartyMemberSort.byDamageDesc(members);
		return members;
	}
}

