	private static final Color[] PALETTE = {
		new Color(100, 180, 255),
		new Color(255, 180, 80),
		new Color(120, 210, 100),
		new Color(200, 130, 255),
		new Color(255, 120, 160),
		new Color(80, 220, 210),
		new Color(255, 220, 90),
		new Color(180, 180, 255),
	};
	private static final Color LOCAL_IDLE_FILL = scale(LOCAL_PLAYER, 0.55f);
	private static final Color LOCAL_LABEL = brighten(LOCAL_PLAYER, 1.15f);
	private static final Color LOCAL_LABEL_IDLE = lift(LOCAL_PLAYER);
	private static final Color[] IDLE_FILL = new Color[PALETTE.length];
	private static final Color[] ACTIVE_LABEL = new Color[PALETTE.length];
	private static final Color[] IDLE_LABEL = new Color[PALETTE.length];

	static
	{
		for (int i = 0; i < PALETTE.length; i++)
		{
			IDLE_FILL[i] = scale(PALETTE[i], 0.55f);
			ACTIVE_LABEL[i] = brighten(PALETTE[i], 1.15f);
			IDLE_LABEL[i] = lift(PALETTE[i]);
		}
	}

	private PartyMemberColors()
	{
	}

	static Color forPlayer(String name, boolean localPlayer)
	{
		if (localPlayer || "You".equalsIgnoreCase(name))
		{
			return LOCAL_PLAYER;
		}

		int index = Math.floorMod(name.hashCode(), PALETTE.length);
		return PALETTE[index];
	}

	static Color barFill(Color base, boolean inCombat)
	{
		if (inCombat)
		{
			return base;
		}

		if (base == LOCAL_PLAYER)
		{
			return LOCAL_IDLE_FILL;
		}

		int index = indexOf(base);
		return index >= 0 ? IDLE_FILL[index] : base;
	}

	static Color labelText(Color base, boolean inCombat)
	{
		if (base == LOCAL_PLAYER)
		{
			return inCombat ? LOCAL_LABEL : LOCAL_LABEL_IDLE;
		}

		int index = indexOf(base);
		if (index < 0)
		{
			return base;
		}

		return inCombat ? ACTIVE_LABEL[index] : IDLE_LABEL[index];
	}

	private static int indexOf(Color base)
	{
		for (int i = 0; i < PALETTE.length; i++)
		{
			if (PALETTE[i] == base)
			{
				return i;
			}
		}
		return -1;
	}

	private static Color scale(Color color, float factor)
	{
		return new Color(
			(int) (color.getRed() * factor),
			(int) (color.getGreen() * factor),
			(int) (color.getBlue() * factor));
	}

	private static Color lift(Color color)
	{
		return new Color(
			Math.min(255, (int) (color.getRed() * 0.75 + 60)),
			Math.min(255, (int) (color.getGreen() * 0.75 + 60)),
			Math.min(255, (int) (color.getBlue() * 0.75 + 60)));
	}

	private static Color brighten(Color color, float factor)
	{
		return new Color(
			Math.min(255, (int) (color.getRed() * factor)),
			Math.min(255, (int) (color.getGreen() * factor)),
			Math.min(255, (int) (color.getBlue() * factor)));
	}
}

package com.spoopdps;

import lombok.Getter;

@Getter
class PartyMemberDpsState
{
	private final long memberId;
	private final String displayName;
	private final DpsMeterSnapshot snapshot;
	private final int totalDamage;
	private final boolean bossFight;
	private final long updatedAtMs;

	static final long LOCAL_MEMBER_ID = -1L;

	PartyMemberDpsState(long memberId, String displayName, DpsMeterSnapshot snapshot,
		int totalDamage, boolean bossFight, long updatedAtMs)
	{
		this.memberId = memberId;
		this.displayName = displayName;
		this.snapshot = snapshot;
		this.totalDamage = totalDamage;
		this.bossFight = bossFight;
		this.updatedAtMs = updatedAtMs;
	}

	static PartyMemberDpsState local(DpsMeterSnapshot snapshot, int totalDamage, boolean bossFight)
	{
		return new PartyMemberDpsState(LOCAL_MEMBER_ID, "You", snapshot, totalDamage, bossFight, System.currentTimeMillis());
	}

	boolean isLocalPlayer()
	{
		return memberId == LOCAL_MEMBER_ID;
	}

	static PartyMemberDpsState fromUpdate(SpoopDpsPartyUpdate update, String displayName)
	{
		DpsMeterSnapshot snapshot = DpsMeterSnapshot.builder()
			.subtitle(update.isInCombat() ? null : update.getTargetLabel())
			.dps(update.getDps())
			.expectedDps(update.getExpectedDps())
			.peakDps(update.getPeakDps())
			.fightElapsedMs(update.getFightElapsedMs())
			.inCombat(update.isInCombat())
			.boomPercent(update.getBoomPercent())
			.whiffPercent(update.getWhiffPercent())
			.attackCount(update.getAttackCount())
			.totalDamage(update.getTotalDamage())
			.build();

		return new PartyMemberDpsState(
			update.getMemberId(),
			displayName,
			snapshot,
			update.getTotalDamage(),
			update.isBossFight(),
			System.currentTimeMillis());
	}

	boolean isVisible(long staleAfterMs)
	{
		if (System.currentTimeMillis() - updatedAtMs > staleAfterMs)
		{
			return false;
		}
		return snapshot.isInCombat() || snapshot.getDps() > 0;
	}
}

package com.spoopdps;

import java.util.Comparator;
import java.util.List;

final class PartyMemberSort
{
	private PartyMemberSort()
	{
	}

	static void byDamageDesc(List<PartyMemberDpsState> members)
	{
		members.sort(Comparator
			.comparingInt(PartyMemberDpsState::getTotalDamage)
			.reversed()
			.thenComparing(m -> m.getSnapshot().getDps(), Comparator.reverseOrder())
			.thenComparing(PartyMemberDpsState::getDisplayName, String.CASE_INSENSITIVE_ORDER));
	}
}

package com.spoopdps;

import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Singleton;

@Singleton
class PartyMeterAnimator
{
	private static final double DPS_SPEED = 14.0;
	private static final double ROW_SPEED = 9.0;
	private static final double DAMAGE_SPEED = 10.0;
	private static final double MARKER_SPEED = 8.0;

	private final Map<String, MemberAnimation> members = new HashMap<>();
	private final Set<String> activeKeys = new HashSet<>();

	void update(List<PartyMemberDpsState> sortedMembers, double deltaSeconds)
	{
		activeKeys.clear();
		Set<String> active = activeKeys;
		for (int i = 0; i < sortedMembers.size(); i++)
		{
			PartyMemberDpsState member = sortedMembers.get(i);
			String key = memberKey(member);
			active.add(key);

			MemberAnimation animation = members.get(key);
			if (animation == null)
			{
				animation = MemberAnimation.from(member, i);
				members.put(key, animation);
			}
			else if (deltaSeconds > 0)
			{
				animation.tick(member, i, deltaSeconds);
			}
			else
			{
				animation.snap(member, i);
			}
		}

		members.keySet().retainAll(active);
	}

	double getSmoothedDps(PartyMemberDpsState member)
	{
		MemberAnimation animation = members.get(memberKey(member));
		return animation != null ? animation.dps : member.getSnapshot().getDps();
	}

	double getSmoothedExpectedDps(PartyMemberDpsState member)
	{
		MemberAnimation animation = members.get(memberKey(member));
		return animation != null ? animation.expectedDps : member.getSnapshot().getExpectedDps();
	}

	double getSmoothedPeakDps(PartyMemberDpsState member)
	{
		MemberAnimation animation = members.get(memberKey(member));
		return animation != null ? animation.peakDps : member.getSnapshot().getPeakDps();
	}

	int getSmoothedDamage(PartyMemberDpsState member)
	{
		MemberAnimation animation = members.get(memberKey(member));
		return animation != null ? (int) Math.round(animation.damage) : member.getTotalDamage();
	}

	double getRowIndex(PartyMemberDpsState member)
	{
		MemberAnimation animation = members.get(memberKey(member));
		return animation != null ? animation.rowIndex : 0;
	}

	static String memberKey(PartyMemberDpsState member)
	{
		if (member.getMemberId() != 0)
		{
			return "id:" + member.getMemberId();
		}
		return "name:" + member.getDisplayName();
	}

	private static final class MemberAnimation
	{
		private double dps;
		private double expectedDps;
		private double peakDps;
		private double damage;
		private double rowIndex;

		private MemberAnimation(double dps, double expectedDps, double peakDps, double damage, double rowIndex)
		{
			this.dps = dps;
			this.expectedDps = expectedDps;
			this.peakDps = peakDps;
			this.damage = damage;
			this.rowIndex = rowIndex;
		}

		static MemberAnimation from(PartyMemberDpsState member, int rowIndex)
		{
			DpsMeterSnapshot snapshot = member.getSnapshot();
			return new MemberAnimation(
				snapshot.getDps(),
				snapshot.getExpectedDps(),
				snapshot.getPeakDps(),
				member.getTotalDamage(),
				rowIndex);
		}

		void snap(PartyMemberDpsState member, int targetRowIndex)
		{
			DpsMeterSnapshot snapshot = member.getSnapshot();
			dps = snapshot.getDps();
			expectedDps = snapshot.getExpectedDps();
			peakDps = snapshot.getPeakDps();
			damage = member.getTotalDamage();
			rowIndex = targetRowIndex;
		}

		void tick(PartyMemberDpsState member, int targetRowIndex, double deltaSeconds)
		{
			DpsMeterSnapshot snapshot = member.getSnapshot();
			dps = smoothToward(dps, snapshot.getDps(), deltaSeconds, DPS_SPEED);
			expectedDps = smoothToward(expectedDps, snapshot.getExpectedDps(), deltaSeconds, MARKER_SPEED);
			peakDps = smoothToward(peakDps, snapshot.getPeakDps(), deltaSeconds, MARKER_SPEED);
			damage = smoothToward(damage, member.getTotalDamage(), deltaSeconds, DAMAGE_SPEED);
			rowIndex = smoothToward(rowIndex, targetRowIndex, deltaSeconds, ROW_SPEED);
		}

		private static double smoothToward(double current, double target, double deltaSeconds, double speed)
		{
			double factor = 1.0 - Math.exp(-speed * deltaSeconds);
			return current + (target - current) * factor;
		}
	}
}

package com.spoopdps;

import java.util.List;

final class PartyMeterScale
{
	private PartyMeterScale()
	{
	}

	static double resolveSharedScale(double localDps, double localExpected, double localPeak,
		List<PartyMemberDpsState> remoteMembers, PartyMeterAnimator animator)
	{
		if (remoteMembers == null || remoteMembers.isEmpty())
		{
			return 0;
		}

		double high = Math.max(localDps, Math.max(localExpected, localPeak));
		for (PartyMemberDpsState member : remoteMembers)
		{
			high = Math.max(high, animator.getSmoothedDps(member));
			high = Math.max(high, animator.getSmoothedExpectedDps(member));
			high = Math.max(high, animator.getSmoothedPeakDps(member));
		}

		return Math.max(high * 1.1, 1.0);
	}
}

package com.spoopdps;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

@Slf4j
@Singleton
class PersonalBestStore
{
	private static final String FILE_NAME = "personal-bests.json";
	private static final int MIN_DAMAGE = 50;
	private static final long MIN_DURATION_MS = 3000;

	private static final Type MAP_TYPE = new TypeToken<Map<String, Double>>(){}.getType();

	@Inject
	private Gson gson;

	private final Map<String, Double> bests = new HashMap<>();
	private Filepath dataDirectory;
	private final ExecutorService saveExecutor = Executors.newSingleThreadExecutor(r ->
	{
		Thread t = new Thread(r, "spoop-dps-pb-save");
		t.setDaemon(true);
		return t;
	});

	private boolean loaded;

	void setDataDirectory(Filepath dataDirectory)
	{
		this.dataDirectory = dataDirectory;
	}

	void load()
	{
		if (loaded || dataDirectory == null)
		{
			return;
		}

		Filepath file = dataDirectory.joinSegment(FILE_NAME);
		if (!file.exists())
		{
			loaded = true;
			return;
		}

		try (var reader = file.openBufferedReader())
		{
			Map<String, Double> data = gson.fromJson(reader, MAP_TYPE);
			if (data != null)
			{
				bests.putAll(data);
			}
		}
		catch (IOException e)
		{
			log.debug("Failed to load personal bests", e);
		}

		loaded = true;
	}

	void shutdown()
	{
		saveExecutor.shutdownNow();
	}

	static String key(String name, int combatLevel)
	{
		return name + ":" + combatLevel;
	}

	Double getBest(String name, int combatLevel)
	{
		return bests.get(key(name, combatLevel));
	}

	Map<String, Double> getAllBests()
	{
		return bests;
	}

	/**
	 * @return true if this fight set a new personal best
	 */
	boolean checkAndUpdate(String name, int combatLevel, double dps, int totalDamage, long durationMs)
	{
		if (totalDamage < MIN_DAMAGE || durationMs < MIN_DURATION_MS || dps <= 0)
		{
			return false;
		}

		String key = key(name, combatLevel);
		Double existing = bests.get(key);
		if (existing != null && dps <= existing)
		{
			return false;
		}

		bests.put(key, dps);
		scheduleSave();
		return true;
	}

	private void scheduleSave()
	{
		saveExecutor.execute(this::save);
	}

	private void save()
	{
		if (dataDirectory == null)
		{
			return;
		}

		try
		{
			Filepath file = dataDirectory.joinSegment(FILE_NAME);
			file.write(gson.toJson(bests));
		}
		catch (IOException e)
		{
			log.debug("Failed to save personal bests", e);
		}
	}
}

