final class PrayerStyles
{
	private static final Color DEFAULT = new Color(180, 180, 180);

	private PrayerStyles()
	{
	}

	static String label(Prayer prayer)
	{
		switch (prayer)
		{
			case PIETY:
				return "Pi";
			case CHIVALRY:
				return "Ch";
