				return "Pr";
			case PROTECT_FROM_MAGIC:
				return "Pg";
			case SMITE:
				return "Sm";
			case REDEMPTION:
				return "Rd";
			case RETRIBUTION:
				return "Rt";
			case PRESERVE:
				return "Ps";
			default:
				return abbreviate(prayer.name());
		}
	}

	static Color color(Prayer prayer)
	{
		switch (prayer)
		{
			case PIETY:
			case CHIVALRY:
			case ULTIMATE_STRENGTH:
			case SUPERHUMAN_STRENGTH:
			case BURST_OF_STRENGTH:
				return new Color(255, 160, 60);
			case RIGOUR:
			case EAGLE_EYE:
			case HAWK_EYE:
			case SHARP_EYE:
				return new Color(100, 200, 100);
			case AUGURY:
			case MYSTIC_MIGHT:
			case MYSTIC_LORE:
			case MYSTIC_WILL:
				return new Color(100, 160, 255);
			case PROTECT_FROM_MELEE:
				return new Color(220, 80, 80);
			case PROTECT_FROM_MISSILES:
				return new Color(80, 200, 120);
			case PROTECT_FROM_MAGIC:
				return new Color(120, 140, 255);
			case STEEL_SKIN:
			case ROCK_SKIN:
			case THICK_SKIN:
				return new Color(160, 160, 160);
			case SMITE:
				return new Color(255, 220, 80);
			default:
				return DEFAULT;
		}
	}

	static boolean isChartPrayer(Prayer prayer)
	{
		switch (prayer)
		{
			case THICK_SKIN:
			case BURST_OF_STRENGTH:
			case CLARITY_OF_THOUGHT:
			case SHARP_EYE:
			case MYSTIC_WILL:
			case ROCK_SKIN:
			case SUPERHUMAN_STRENGTH:
			case IMPROVED_REFLEXES:
			case HAWK_EYE:
			case MYSTIC_LORE:
			case STEEL_SKIN:
			case ULTIMATE_STRENGTH:
			case INCREDIBLE_REFLEXES:
			case EAGLE_EYE:
			case MYSTIC_MIGHT:
			case CHIVALRY:
			case PIETY:
			case RIGOUR:
			case AUGURY:
			case PROTECT_FROM_MAGIC:
			case PROTECT_FROM_MISSILES:
			case PROTECT_FROM_MELEE:
			case SMITE:
			case REDEMPTION:
			case RETRIBUTION:
			case PRESERVE:
				return true;
			default:
				return false;
		}
	}

	private static String abbreviate(String name)
	{
		int underscore = name.indexOf('_');
		if (underscore >= 0 && underscore + 2 < name.length())
		{
			return "" + name.charAt(0) + name.charAt(underscore + 1);
		}
		return name.length() >= 2 ? name.substring(0, 2) : name;
	}
}

