package com.spoopdps;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class SpoopDpsOverlay extends Overlay
{
	private static final double DPS_SMOOTH_SPEED = 16.0;
	private static final double SCALE_SMOOTH_SPEED = 8.0;

	@Inject
	private CombatTracker combatTracker;

	@Inject
	private PartyDpsTracker partyDpsTracker;

	@Inject
	private PartyDamageTracker partyDamageTracker;

	@Inject
	private PersonalBestStore personalBestStore;

	@Inject
	private SpoopDpsConfig config;

	@Inject
	private PartyMeterAnimator partyMeterAnimator;

	private final List<PartyMemberDpsState> drawOrder = new ArrayList<>();
	private final List<PartyMemberDpsState> paintOrder = new ArrayList<>();
	private double smoothedDps;
	private double smoothedExpectedDps;
	private double smoothedPeakDps;
	private long lastSmoothNanos;
	private Instant trackedSessionStart;
	private boolean smoothingInitialized;

	SpoopDpsOverlay()
	{
		setPosition(OverlayPosition.TOP_RIGHT);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
		setMovable(true);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showLiveDpsBox())
		{
			return null;
		}

		MeterSize mainSize = config.meterSize();
		MeterSize partySize = DpsMeterRenderer.partyRowSize(mainSize);

		CombatSession session = combatTracker.getOverlaySession();
		boolean inCombat = combatTracker.isInCombat();
		List<PartyMemberDpsState> remoteMembers = partyDpsTracker.getDisplayedPartyMembers();
		int partyTotal = 0;
		boolean bossEncounter = session != null && session.isBossFight();
		boolean showBossPercent = config.showBossDamagePercent()
			&& bossEncounter
			&& (config.partyDps() || partyDamageTracker.getOthersDamageForDisplay() > 0);

		if (showBossPercent)
		{
			partyTotal = partyDamageTracker.getPartyTotalDamage(session, remoteMembers);
		}

		long frameNanos = System.nanoTime();
		double deltaSeconds = lastSmoothNanos == 0 ? 0 : (frameNanos - lastSmoothNanos) / 1_000_000_000.0;
		lastSmoothNanos = frameNanos;

		int x = 0;
		int maxWidth = 0;
		boolean showBossHeader = bossEncounter;
		String bossHeaderLabel = showBossHeader ? resolveBossHeaderLabel(session) : null;
		int headerOffset = showBossHeader ? DpsMeterRenderer.BOSS_HEADER_HEIGHT + 4 : 0;
		int y = headerOffset;
		boolean hasPartyRows = !remoteMembers.isEmpty();

		DpsMeterSnapshot target = null;
		if (session == null)
		{
			resetSmoothing(null);
		}
		else
		{
			if (trackedSessionStart == null || !trackedSessionStart.equals(session.getStartTime()))
			{
				resetSmoothing(session);
			}

			target = buildTargetSnapshot(session, inCombat);
			if (!smoothingInitialized)
			{
				smoothedDps = target.getDps();
				smoothedExpectedDps = target.getExpectedDps();
				smoothedPeakDps = target.getPeakDps();
				smoothingInitialized = true;
			}
			else if (deltaSeconds > 0)
			{
				smoothedDps = smoothToward(smoothedDps, target.getDps(), deltaSeconds, DPS_SMOOTH_SPEED);
				smoothedExpectedDps = smoothToward(smoothedExpectedDps, target.getExpectedDps(), deltaSeconds, SCALE_SMOOTH_SPEED);
				smoothedPeakDps = smoothToward(smoothedPeakDps, target.getPeakDps(), deltaSeconds, SCALE_SMOOTH_SPEED);
			}
		}

		if (hasPartyRows)
		{
			drawOrder.clear();
			drawOrder.add(buildLocalMember(session, target, bossEncounter));
			drawOrder.addAll(remoteMembers);
			PartyMemberSort.byDamageDesc(drawOrder);
			partyMeterAnimator.update(drawOrder, deltaSeconds);
		}

		double sharedScale = hasPartyRows && config.showExpectedDps()
			? PartyMeterScale.resolveSharedScale(
				smoothedDps, smoothedExpectedDps, smoothedPeakDps, drawOrder, partyMeterAnimator)
			: 0;

		if (!hasPartyRows)
		{
			if (session == null)
			{
				String localLabel = mainSize == MeterSize.THIN ? "You" : null;
				Color localColor = PartyMemberColors.forPlayer("You", true);
				Dimension localSize = DpsMeterRenderer.drawMeter(
					graphics, x, y,
					DpsMeterSnapshot.builder().dps(0).inCombat(false).build(),
					config, localLabel, mainSize, true, localColor, sharedScale);
				maxWidth = Math.max(maxWidth, localSize.width);
				y += localSize.height;
			}
			else
			{
				var displayBuilder = DpsMeterSnapshot.builder()
					.subtitle(target.getSubtitle())
					.dps(smoothedDps)
					.expectedDps(smoothedExpectedDps)
					.peakDps(smoothedPeakDps)
					.fightElapsedMs(target.getFightElapsedMs())
					.inCombat(inCombat)
				.boomPercent(target.getBoomPercent())
				.whiffPercent(target.getWhiffPercent())
				.boomCount(target.getBoomCount())
				.whiffCount(target.getWhiffCount())
					.attackCount(target.getAttackCount())
					.totalDamage(session.getTotalDamage());

				if (showBossPercent && partyTotal > 0)
				{
					displayBuilder.damagePercent(partyDamageTracker.getDamagePercent(session.getTotalDamage(), partyTotal));
				}

				if (isAbovePersonalBest(session, smoothedDps))
				{
					displayBuilder.abovePersonalBest(true);
				}

				String localLabel = mainSize == MeterSize.THIN ? "You" : null;
				Color localColor = PartyMemberColors.forPlayer("You", true);
				Dimension localSize = DpsMeterRenderer.drawMeter(
					graphics, x, y, displayBuilder.build(), config, localLabel, mainSize, true,
					localColor, sharedScale);
				maxWidth = Math.max(maxWidth, localSize.width);
				y += localSize.height;
			}
		}
		else
		{
			int partyStartY = y;
			int rowStride = DpsMeterRenderer.estimatedRowHeight(partySize) + DpsMeterRenderer.ROW_GAP;

			paintOrder.clear();
			paintOrder.addAll(drawOrder);
			paintOrder.sort(Comparator.comparingDouble(partyMeterAnimator::getRowIndex));

			for (PartyMemberDpsState member : paintOrder)
			{
				DpsMeterSnapshot snapshot = member.getSnapshot();
				int smoothedDamage = partyMeterAnimator.getSmoothedDamage(member);
				double memberDps = partyMeterAnimator.getSmoothedDps(member);
				boolean local = member.isLocalPlayer();
				var builder = DpsMeterSnapshot.builder()
					.subtitle(snapshot.getSubtitle())
					.dps(memberDps)
					.expectedDps(partyMeterAnimator.getSmoothedExpectedDps(member))
					.peakDps(partyMeterAnimator.getSmoothedPeakDps(member))
					.fightElapsedMs(snapshot.getFightElapsedMs())
					.inCombat(snapshot.isInCombat())
					.boomPercent(snapshot.getBoomPercent())
					.whiffPercent(snapshot.getWhiffPercent())
					.attackCount(snapshot.getAttackCount())
					.totalDamage(smoothedDamage);

				if (showBossPercent && member.isBossFight() && partyTotal > 0 && smoothedDamage > 0)
				{
					builder.damagePercent(partyDamageTracker.getDamagePercent(smoothedDamage, partyTotal));
				}

				if (local && session != null && isAbovePersonalBest(session, memberDps))
				{
					builder.abovePersonalBest(true);
				}

				int drawY = partyStartY + (int) Math.round(partyMeterAnimator.getRowIndex(member) * rowStride);
				Color memberColor = PartyMemberColors.forPlayer(member.getDisplayName(), local);
				Dimension size = DpsMeterRenderer.drawMeter(
					graphics, x, drawY, builder.build(), config, member.getDisplayName(), partySize, false,
					memberColor, sharedScale);
				maxWidth = Math.max(maxWidth, size.width);
			}

			y = partyStartY + drawOrder.size() * rowStride - DpsMeterRenderer.ROW_GAP;
		}

		if (showBossHeader && bossHeaderLabel != null && maxWidth > 0)
		{
			Dimension headerSize = DpsMeterRenderer.drawBossHeader(
				graphics, x, 0, bossHeaderLabel, inCombat, maxWidth);
			maxWidth = Math.max(maxWidth, headerSize.width);
		}

		return y > 0 ? new Dimension(maxWidth, y) : null;
	}

	private static String resolveBossHeaderLabel(CombatSession session)
	{
		TargetStats primary = session.getPrimaryTarget();
		if (primary == null)
		{
			return session.getHistoryLabel();
		}

		return primary.getName() + " (lvl " + primary.getCombatLevel() + ")";
	}

	private PartyMemberDpsState buildLocalMember(CombatSession session, DpsMeterSnapshot target, boolean bossFight)
	{
		DpsMeterSnapshot snapshot = target != null
			? target
			: DpsMeterSnapshot.builder().dps(0).inCombat(false).build();
		int damage = session != null ? session.getTotalDamage() : 0;
		return PartyMemberDpsState.local(snapshot, damage, bossFight);
	}

	private DpsMeterSnapshot buildTargetSnapshot(CombatSession session, boolean inCombat)
	{
		DpsMeterSnapshot snapshot = DpsMeterSnapshot.fromSession(session, inCombat, config);
		return snapshot;
	}

	private boolean isAbovePersonalBest(CombatSession session, double displayDps)
	{
		TargetStats primary = session.getPrimaryTarget();
		if (primary == null || displayDps <= 0)
		{
			return false;
		}

		Double pb = personalBestStore.getBest(primary.getName(), primary.getCombatLevel());
		return pb != null && displayDps > pb;
	}

	private void resetSmoothing(CombatSession session)
	{
		trackedSessionStart = session != null ? session.getStartTime() : null;
		smoothingInitialized = false;
		smoothedDps = 0;
		smoothedExpectedDps = 0;
		smoothedPeakDps = 0;
		lastSmoothNanos = 0;
	}

	private static double smoothToward(double current, double target, double deltaSeconds, double speed)
	{
		double factor = 1.0 - Math.exp(-speed * deltaSeconds);
		return current + (target - current) * factor;
	}
}

package com.spoopdps;

import java.awt.BorderLayout;
