	private void showSession(CombatSession session, boolean active)
	{
		statusLabel.setText(active ? "In combat" : "Last fight");
		statusLabel.setForeground(active ? ColorScheme.PROGRESS_COMPLETE_COLOR : ColorScheme.LIGHT_GRAY_COLOR);

		String dpsText = DPS_FORMAT.format(session.getDps()) + " DPS";
		TargetStats primary = session.getPrimaryTarget();
		if (primary != null)
		{
			Double pb = personalBestStore.getBest(primary.getName(), primary.getCombatLevel());
			if (pb != null)
			{
				dpsText += " · PB " + DPS_FORMAT.format(pb);
			}
		}
		dpsLabel.setText(dpsText);

		summaryLabel.setText(String.format("%s dmg  ·  %s  ·  %d hits (max %d)",
			QuantityFormatter.formatNumber(session.getTotalDamage()),
			session.getFormattedDuration(),
			session.getHitCount(),
			session.getMaxHit()));

		PlayerSnapshot player = session.getPlayerSnapshot();
		styleLabel.setText("CB " + player.getCombatLevel() + "  ·  " + player.getStyleLabel());
		luckLabel.setText(session.getLuckSummary().isEmpty() ? " " : session.getLuckSummary());
	}

	private void showIdle()
	{
		statusLabel.setText("Out of combat");
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		dpsLabel.setText("—");
		summaryLabel.setText("Attack something to start tracking");
		styleLabel.setText(" ");
		luckLabel.setText(" ");
	}

	private void rebuildTargets(CombatSession session)
	{
		int signature = targetPanelSignature(session);
		if (signature == renderedTargetSignature)
		{
			return;
		}
		renderedTargetSignature = signature;

		targetsPanel.removeAll();

		if (session == null || session.getTargetsByDamage().isEmpty())
		{
			targetsPanel.add(mutedLabel("No targets yet"));
			targetsPanel.revalidate();
			targetsPanel.repaint();
			return;
		}

		long elapsedMs = session.getElapsedMs();
		int totalDamage = session.getTotalDamage();

		for (TargetStats target : session.getTargetsByDamage())
		{
			targetsPanel.add(buildTargetRow(target, elapsedMs, totalDamage, session.isActive()));
		}

		targetsPanel.revalidate();
		targetsPanel.repaint();
	}

	private JPanel buildTargetRow(TargetStats target, long elapsedMs, int totalDamage, boolean active)
	{
		JPanel row = new JPanel(new BorderLayout(0, 2));
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);

		String hp = active ? "  ·  " + target.getHpPercent() + "% HP" : "";
		JLabel name = new JLabel(String.format("%s (lvl %d)%s",
			target.getName(), target.getCombatLevel(), hp));
		name.setForeground(Color.WHITE);
		name.setFont(name.getFont().deriveFont(BODY_SIZE));

		JLabel stats = new JLabel(String.format("%s  ·  %s DPS  ·  %d hits",
			QuantityFormatter.formatNumber(target.getDamage()),
			DPS_FORMAT.format(target.getDps(elapsedMs)),
			target.getHits()));
		stats.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		stats.setFont(stats.getFont().deriveFont(BODY_SIZE));

		JPanel labels = new JPanel(new GridLayout(2, 1, 0, 0));
		labels.setBackground(ColorScheme.DARK_GRAY_COLOR);
		labels.add(name);
		labels.add(stats);
		row.add(labels, BorderLayout.NORTH);

		JProgressBar bar = new JProgressBar(0, 100);
		int share = (int) Math.round(target.getDamageShare(totalDamage));
		bar.setValue(Math.max(0, Math.min(100, share)));
		bar.setString(share + "% of damage");
		styleBar(bar, TARGET_BAR);
		bar.setPreferredSize(new Dimension(0, 12));
		row.add(bar, BorderLayout.SOUTH);

		return row;
	}

	private void selectHistoryTab(boolean party)
	{
		if (partyHistoryTab == party)
		{
			return;
		}

		partyHistoryTab = party;
		styleHistoryTab(soloTabButton, !party);
		styleHistoryTab(partyTabButton, party);
		renderedHistoryGeneration = -1;
		rebuildHistory();
	}

	private void rebuildHistory()
	{
		int generation = combatTracker.getHistoryGeneration();
		if (generation == renderedHistoryGeneration && partyHistoryTab == renderedPartyTab)
		{
			return;
		}
		renderedHistoryGeneration = generation;
		renderedPartyTab = partyHistoryTab;

		historySummaryPanel.removeAll();
		historyPanel.removeAll();

		List<CombatSession> filtered = new ArrayList<>();
		for (CombatSession session : combatTracker.getHistory())
		{
			if (session.isBossFight() == partyHistoryTab)
			{
				filtered.add(session);
			}
		}

		if (partyHistoryTab)
		{
			historyLogSection.setVisible(false);
			rebuildPartyHistory(filtered);
		}
		else
		{
			rebuildSoloHistory(filtered);
		}

		historySummaryPanel.revalidate();
		historySummaryPanel.repaint();
		historyLogSection.revalidate();
		historyLogSection.repaint();
		historyPanel.revalidate();
		historyPanel.repaint();
	}

	private void rebuildSoloHistory(List<CombatSession> fights)
	{
		if (fights.isEmpty())
		{
			historySummaryPanel.add(mutedLabel("No solo fights yet"));
			historyLogSection.setVisible(false);
			return;
		}

		historyLogSection.setVisible(true);
		List<EnemyHistorySummary> summaries = summarizeHistory(fights);
		JPanel summaryStack = new JPanel();
		summaryStack.setLayout(new BoxLayout(summaryStack, BoxLayout.Y_AXIS));
		summaryStack.setBackground(ColorScheme.DARK_GRAY_COLOR);
		summaryStack.setAlignmentX(Component.LEFT_ALIGNMENT);
		for (EnemyHistorySummary summary : summaries)
		{
			summaryStack.add(buildHistorySummaryBox(summary));
		}
		historySummaryPanel.add(summaryStack);

		for (CombatSession session : fights)
		{
			historyPanel.add(buildHistoryRow(session));
		}

		updateHistoryLogToggleLabel(fights.size());
		historyPanel.setVisible(historyLogExpanded);
	}

	private void rebuildPartyHistory(List<CombatSession> fights)
	{
		if (fights.isEmpty())
		{
			historySummaryPanel.add(mutedLabel("No boss fights yet"));
			return;
		}

		for (CombatSession session : fights)
		{
			historySummaryPanel.add(buildBossHistoryRow(session));
		}
	}

	private List<EnemyHistorySummary> summarizeHistory(List<CombatSession> fights)
	{
		java.util.Map<String, EnemyHistorySummary> summaries = new java.util.LinkedHashMap<>();
		for (CombatSession session : fights)
		{
			summaries.computeIfAbsent(session.getHistoryLabel(), EnemyHistorySummary::new).addSession(session);
		}
		return new ArrayList<>(summaries.values());
	}

	private void toggleHistoryLog()
	{
		historyLogExpanded = !historyLogExpanded;
		historyPanel.setVisible(historyLogExpanded);
		updateHistoryLogToggleLabel(combatTracker.getHistory().size());
		historyLogSection.revalidate();
		historyLogSection.repaint();
	}

	private void updateHistoryLogToggleLabel(int fightCount)
	{
		String arrow = historyLogExpanded ? "\u25BC" : "\u25B6";
		String suffix = fightCount == 1 ? " (1 fight)" : " (" + fightCount + " fights)";
		historyLogToggle.setText(arrow + " Fight log" + suffix);
	}

	private JPanel buildBossHistoryRow(CombatSession session)
	{
		BossRecap recap = session.getBossRecap();

		JPanel box = new JPanel();
		box.setLayout(new BoxLayout(box, BoxLayout.Y_AXIS));
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(BorderFactory.createCompoundBorder(
			new EmptyBorder(0, 0, 8, 0),
			BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
				new EmptyBorder(8, 8, 8, 8)
			)
		));

		JLabel title = textLabel(session.getHistoryLabel(), Color.WHITE, TITLE_SIZE, true);
		title.setMinimumSize(new Dimension(0, title.getPreferredSize().height));

		JButton shareButton = new JButton("Share");
		shareButton.setFocusable(false);
		shareButton.setFont(shareButton.getFont().deriveFont(BODY_SIZE));
		shareButton.addActionListener(e -> copyBossShare(session));

		JPanel header = new JPanel(new BorderLayout(8, 0));
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.add(title, BorderLayout.CENTER);
		header.add(shareButton, BorderLayout.EAST);
		addStacked(box, header);
		addStacked(box, textLabel(session.getFormattedDuration(), ColorScheme.LIGHT_GRAY_COLOR, BODY_SIZE, false));

		if (recap == null || recap.getMembers().isEmpty())
		{
			addStacked(box, splitLine("You", damageTotal(100, session.getTotalDamage())));
		}
		else
		{
			for (BossRecap.BossRecapMember member : recap.getMembers())
			{
				if (member.getDamage() <= 0)
				{
					continue;
				}

				String name = member.isLocalPlayer() ? member.getName() + " (you)" : member.getName();
				addStacked(box, splitLine(name, damageTotal(member.getDamagePercent(), member.getDamage())));
			}
		}

		fitStacked(box);
		return box;
	}

	private void copyBossShare(CombatSession session)
	{
		BossRecap recap = session.getBossRecap();
		String text = recap != null
			? recap.toClipboardText()
			: session.getHistoryLabel() + "\n" + localShareLine(session);
		if (text == null || text.isEmpty())
		{
			return;
		}

		StringSelection selection = new StringSelection(text);
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(selection, selection);
	}

	private static String localShareLine(CombatSession session)
	{
		return "You  100%  " + QuantityFormatter.formatNumber(session.getTotalDamage());
	}

	private static String damageTotal(double percent, int damage)
	{
		return String.format("%.0f%%   ·   %s", percent, QuantityFormatter.formatNumber(damage));
	}

	private static JLabel textLabel(String text, Color color, float size, boolean bold)
	{
		JLabel label = new JLabel(text);
		label.setForeground(color);
		label.setFont(label.getFont().deriveFont(bold ? Font.BOLD : Font.PLAIN, size));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		return label;
	}

	private static JPanel splitLine(String left, String right)
	{
		JPanel row = new JPanel(new BorderLayout(8, 0));
		row.setOpaque(false);
		row.setBorder(new EmptyBorder(3, 0, 0, 0));
		JLabel name = textLabel(left, ColorScheme.LIGHT_GRAY_COLOR, BODY_SIZE, false);
		name.setMinimumSize(new Dimension(0, name.getPreferredSize().height));
		JLabel total = textLabel(right, ACCENT, BODY_SIZE, false);
		row.add(name, BorderLayout.CENTER);
		row.add(total, BorderLayout.EAST);
		return row;
	}

	private static void addStacked(JComponent parent, JComponent child)
	{
		child.setAlignmentX(Component.LEFT_ALIGNMENT);
		parent.add(child);
	}

	private static void fitStacked(JComponent component)
	{
		component.setAlignmentX(Component.LEFT_ALIGNMENT);
		int height = Math.max(component.getPreferredSize().height, 1);
		component.setMinimumSize(new Dimension(0, height));
		component.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
	}

	private static void styleHistoryTab(JButton button, boolean selected)
	{
		button.setFocusable(false);
		button.setFont(button.getFont().deriveFont(selected ? Font.BOLD : Font.PLAIN, BODY_SIZE));
		button.setForeground(selected ? ACCENT : ColorScheme.LIGHT_GRAY_COLOR);
		button.setBackground(selected ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.DARK_GRAY_COLOR);
	}

	private JPanel buildHistorySummaryBox(EnemyHistorySummary summary)
	{
		JPanel box = new JPanel(new BorderLayout(8, 0));
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(BorderFactory.createCompoundBorder(
			new EmptyBorder(0, 0, 6, 0),
			BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
				new EmptyBorder(8, 10, 8, 10)
			)
		));
		box.setAlignmentX(Component.LEFT_ALIGNMENT);
		box.setMaximumSize(new Dimension(Integer.MAX_VALUE, 56));

		JLabel name = new JLabel(summary.getName());
		name.setForeground(Color.WHITE);
		name.setFont(name.getFont().deriveFont(Font.BOLD, TITLE_SIZE));

		String dpsText = DPS_FORMAT.format(summary.getAverageDps()) + " avg DPS";
		Double pb = findBestPbForName(summary.getName());
		if (pb != null)
		{
			dpsText += " · PB " + DPS_FORMAT.format(pb);
		}
		JLabel dps = new JLabel(dpsText);
		dps.setForeground(ACCENT);
		dps.setFont(dps.getFont().deriveFont(BODY_SIZE));
		dps.setHorizontalAlignment(SwingConstants.CENTER);

		String killText = summary.getKillCount() == 1 ? "1 kill" : summary.getKillCount() + " kills";
		JLabel kills = new JLabel(killText);
		kills.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		kills.setFont(kills.getFont().deriveFont(BODY_SIZE));
		kills.setHorizontalAlignment(SwingConstants.RIGHT);

		box.add(name, BorderLayout.WEST);
		box.add(dps, BorderLayout.CENTER);
		box.add(kills, BorderLayout.EAST);
		return box;
	}

	private JPanel buildHistoryRow(CombatSession session)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARK_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARKER_GRAY_COLOR),
			new EmptyBorder(3, 0, 3, 0)
		));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));

		JLabel line = new JLabel(String.format("%s  ·  %s DPS  ·  %s dmg  ·  %s",
			session.getHistoryLabel(),
			DPS_FORMAT.format(session.getDps()),
			QuantityFormatter.formatNumber(session.getTotalDamage()),
			session.getFormattedDuration()));
		line.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		line.setFont(line.getFont().deriveFont(13f));
		row.add(line, BorderLayout.CENTER);
		return row;
	}

	private static JLabel sectionTitle(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		label.setFont(label.getFont().deriveFont(Font.BOLD, BODY_SIZE));
		label.setBorder(new EmptyBorder(0, 0, 4, 0));
		return label;
	}

	private static JLabel mutedLabel(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(ColorScheme.MEDIUM_GRAY_COLOR);
		return label;
	}

	private static int targetPanelSignature(CombatSession session)
	{
		if (session == null)
		{
			return 0;
		}

		int signature = session.getTotalDamage();
		signature = 31 * signature + session.getHitCount();
		signature = 31 * signature + (session.isActive() ? 1 : 0);
		TargetStats primary = session.getPrimaryTarget();
		if (primary != null)
		{
			signature = 31 * signature + primary.getNpcIndex();
			signature = 31 * signature + primary.getHpPercent();
			signature = 31 * signature + primary.getDamage();
		}
		return signature;
	}

	private Double findBestPbForName(String name)
	{
		// History summaries group by name only; show the best PB across combat levels for that name.
		Double best = null;
		String prefix = name + ":";
		for (Map.Entry<String, Double> entry : personalBestStore.getAllBests().entrySet())
		{
			if (entry.getKey().startsWith(prefix))
			{
				if (best == null || entry.getValue() > best)
				{
					best = entry.getValue();
				}
			}
		}
		return best;
	}

	private static void styleBar(JProgressBar bar, Color color)
	{
		bar.setForeground(color);
		bar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bar.setBorder(BorderFactory.createLineBorder(ColorScheme.DARKER_GRAY_COLOR));
		bar.setStringPainted(true);
	}
}

