@Slf4j
@PluginDescriptor(
	name = "spoopDPS",
	internalName = "spoop-dps",
	description = "Track your DPS, damage, and combat stats per encounter",
	tags = {"combat", "dps", "damage", "stats", "spoop"}
)
public class SpoopDpsPlugin extends Plugin
{
	private static final BufferedImage ICON = createIcon();

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private CombatTracker combatTracker;

	@Inject
	private SpoopDpsPanel panel;

	@Inject
	private SpoopDpsOverlay spoopDpsOverlay;

	@Inject
	private PartyDpsTracker partyDpsTracker;

	@Inject
	private PartyDamageTracker partyDamageTracker;

	@Inject
	private PersonalBestStore personalBestStore;

	@Inject
	private WSClient wsClient;

	@Inject
	private SpoopDpsConfig config;

	private NavigationButton navButton;
	private ScheduledExecutorService executor;
	private ScheduledFuture<?> refreshTask;

	@Override
	protected void startUp()
	{
		try
		{
			personalBestStore.setDataDirectory(getPluginDirectory());
			personalBestStore.load();
		}
		catch (IOException e)
		{
			log.debug("Failed to initialize personal best storage", e);
		}

		navButton = NavigationButton.builder()
			.tooltip("spoopDPS")
			.icon(ICON)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(spoopDpsOverlay);
		wsClient.registerMessage(SpoopDpsPartyUpdate.class);

		executor = Executors.newSingleThreadScheduledExecutor(r ->
		{
			Thread t = new Thread(r, "spoop-dps-refresh");
			t.setDaemon(true);
			return t;
		});
		refreshTask = executor.scheduleAtFixedRate(this::refreshPanel, 0, 500, TimeUnit.MILLISECONDS);

		log.debug("spoopDPS started");
	}

	@Override
	protected void shutDown()
	{
		if (refreshTask != null)
		{
			refreshTask.cancel(true);
		}
		if (executor != null)
		{
			executor.shutdownNow();
		}

		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(spoopDpsOverlay);
		wsClient.unregisterMessage(SpoopDpsPartyUpdate.class);
		partyDpsTracker.clear();
		partyDamageTracker.clearRecap();
		personalBestStore.shutdown();
		combatTracker.reset();

		log.debug("spoopDPS stopped");
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (client.getLocalPlayer() == null)
		{
			return;
		}

		Actor actor = event.getActor();
		Hitsplat hitsplat = event.getHitsplat();

		if (actor instanceof NPC)
		{
			NPC npc = (NPC) actor;
			if (hitsplat.isMine())
			{
				combatTracker.recordPlayerAttack(npc, hitsplat);
				return;
			}

			if (hitsplat.isOthers() && hitsplat.getAmount() > 0)
			{
				partyDamageTracker.recordOthersDamage(npc, hitsplat.getAmount());
			}
		}

		if (hitsplat.getAmount() <= 0)
		{
			return;
		}

		if (actor == client.getLocalPlayer())
		{
			combatTracker.recordCombatActivity();
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!(event.getActor() instanceof NPC))
		{
			return;
		}

		combatTracker.onTargetDeath((NPC) event.getActor());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		if (npc.isDead())
		{
			combatTracker.onTargetDeath(npc);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		combatTracker.tick(config.combatTimeout());
	}

	@Subscribe
	public void onPartyChanged(PartyChanged partyChanged)
	{
		partyDpsTracker.clear();
	}

	@Subscribe
	public void onSpoopDpsPartyUpdate(SpoopDpsPartyUpdate update)
	{
		partyDpsTracker.onPartyUpdate(update);
	}

	@Provides
	SpoopDpsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SpoopDpsConfig.class);
	}

	private void refreshPanel()
	{
		clientThread.invoke(() ->
		{
			partyDpsTracker.broadcastLocalState(config);
			SwingUtilities.invokeLater(panel::refresh);
		});
	}

	private static BufferedImage createIcon()
	{
		try (InputStream in = SpoopDpsPlugin.class.getResourceAsStream("/icon.png"))
		{
			if (in != null)
			{
				return ImageIO.read(in);
			}
		}
		catch (IOException e)
		{
			log.debug("Failed to load icon.png", e);
		}

		BufferedImage fallback = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		java.awt.Graphics2D g = fallback.createGraphics();
		g.setColor(new java.awt.Color(198, 40, 40));
		g.fillRect(2, 2, 12, 12);
		g.setColor(java.awt.Color.WHITE);
		g.drawString("D", 4, 12);
		g.dispose();
		return fallback;
	}
}

package com.spoopdps;

import lombok.Getter;
import lombok.Setter;

@Getter
@Setter
class TargetStats
{
	private final int npcIndex;
	private final int npcId;
	private final String name;
	private final int combatLevel;
	private int hpPercent;
	private int damage;
	private int hits;
	private int maxHit;

	TargetStats(int npcIndex, int npcId, String name, int combatLevel, int hpPercent)
	{
		this.npcIndex = npcIndex;
		this.npcId = npcId;
		this.name = name;
		this.combatLevel = combatLevel;
		this.hpPercent = hpPercent;
	}

	void addHit(int amount)
	{
		damage += amount;
		hits++;
		maxHit = Math.max(maxHit, amount);
	}

	double getDps(long elapsedMs)
	{
		if (elapsedMs <= 0 || damage == 0)
		{
			return 0;
		}
		return damage / (elapsedMs / 1000.0);
	}

	double getDamageShare(int totalDamage)
	{
		if (totalDamage <= 0)
		{
			return 0;
		}
		return (damage * 100.0) / totalDamage;
	}
}

